BEGIN;

DO $$ 
DECLARE
    v_topic_id UUID;
BEGIN
    -- Ensure the topic exists
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'peds-emergencies-pals' LIMIT 1;
    
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic "peds-emergencies-pals" not found. Please ensure it is seeded in the database.';
    END IF;

    -- Idempotent delete for this topic
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- Insert MCQs (1-370)

END $$;

COMMIT;
