    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: During a pediatric cardiac arrest, what is the recommended depth of chest compressions for an infant (less than 1 year old)?', '["At least one third of the AP diameter of the chest (about 1.5 inches)", "At least one half of the AP diameter of the chest", "Exactly 2 inches", "At least one third of the AP diameter of the chest (about 2 inches)"]', 0, 'For infants, compression depth should be at least 1/3 the AP diameter of the chest, which is approximately 1.5 inches (4 cm). For children, it is also 1/3 the AP diameter but approximately 2 inches (5 cm). (PALS Guidelines)'),
    (v_topic_id, '2: What is the recommended compression-to-ventilation ratio for two-rescuer CPR in a child or infant?', '["30:2", "15:2", "3:1", "15:1"]', 1, 'In pediatric PALS, the ratio changes from 30:2 (single rescuer) to 15:2 when a second rescuer arrives to provide more frequent ventilations. (PALS Guidelines)'),
    (v_topic_id, '3: A 3-year-old child is found unresponsive. You palpate for a pulse but are unsure if one is present. What is the maximum time you should spend checking for a pulse before starting compressions?', '["5 seconds", "10 seconds", "15 seconds", "20 seconds"]', 1, 'Pulse checks in all age groups should take no more than 10 seconds. If a pulse is not definitely felt within 10 seconds, start CPR. (PALS Guidelines)'),
    (v_topic_id, '4: In a pediatric patient with a pulse but inadequate breathing (rescue breathing), what is the recommended ventilation rate?', '["1 breath every 2-3 seconds (20-30 breaths/min)", "1 breath every 5-6 seconds (10-12 breaths/min)", "1 breath every 1 second", "1 breath every 10 seconds"]', 0, 'The 2020 PALS update increased the rescue breathing rate to 1 breath every 2-3 seconds for infants and children with a pulse. (PALS Guidelines)'),
    (v_topic_id, '5: Which of the following is the most common cause of cardiac arrest in the pediatric population?', '["Primary cardiac arrhythmia (e.g., VF)", "Respiratory failure or shock", "Congenital heart disease", "Electrolyte imbalance"]', 1, 'Unlike adults, where cardiac arrest is usually primary (cardiac), pediatric arrest is typically the terminal result of progressive respiratory failure or shock. (Nelson Essentials)'),
    (v_topic_id, '6: A 6-month-old infant is brought to the ER with a barky cough, inspiratory stridor at rest, and significant retractions. What is the first-line medical treatment for this severe presentation?', '["Inhaled albuterol", "Nebulized epinephrine and corticosteroids (e.g., Dexamethasone)", "Intravenous antibiotics", "Inhaled saline"]', 1, 'Laryngotracheobronchitis (Croup) with stridor at rest is treated with nebulized racemic epinephrine (for immediate effect) and corticosteroids (for sustained effect). (Blueprints Pediatrics)'),
    (v_topic_id, '7: A 4-year-old unimmunized child presents with high fever, drooling, muffled voice, and is sitting in a "tripod" position. What is the most appropriate next step in management?', '["Perform a thorough throat exam with a tongue blade", "Obtain a lateral neck X-ray immediately", "Maintain a calm environment and prepare for urgent airway management in the OR", "Start IV antibiotics and nebulized epinephrine"]', 2, 'Suspicion of Epiglottitis (likely H. influenzae type b in unimmunized) is a medical emergency. Avoid agitating the child (no tongue blades) and secure the airway in a controlled environment. (Nelson Essentials)'),
    (v_topic_id, '8: Which physical exam finding is most suggestive of lower airway obstruction (e.g., asthma, bronchiolitis) rather than upper airway obstruction?', '["Inspiratory stridor", "Expiratory wheezing", "Barky cough", "Muffled voice"]', 1, 'Upper airway obstruction typically causes stridor (usually inspiratory). Lower airway obstruction (below the glottis) typically causes wheezing (usually expiratory) and a prolonged expiratory phase. (BRS Pediatrics)'),
    (v_topic_id, '9: A 10-month-old infant presents during winter with rhinorrhea, cough, and diffuse expiratory wheezing. The infant is tachypneic but has no history of atopy. What is the most likely diagnosis and causative agent?', '["Asthma; Rhinovirus", "Bronchiolitis; Respiratory Syncytial Virus (RSV)", "Croup; Parainfluenza", "Pneumonia; S. pneumoniae"]', 1, 'Bronchiolitis is common in infants < 2 years, peaking in winter, and RSV is the most common cause. (Nelson Essentials)'),
    (v_topic_id, '10: A 2-year-old child presents with sudden onset of coughing and unilateral wheezing while playing with small toys. The chest X-ray shows hyperinflation of the right lung. What is the most likely diagnosis?', '["Asthma exacerbation", "Foreign body aspiration", "Right-sided pneumonia", "Bronchiolitis"]', 1, 'Sudden onset and focal (unilateral) wheezing or decreased breath sounds strongly suggest foreign body aspiration. Hyperinflation indicates a "ball-valve" obstruction. (Case Files Pediatrics)'),
    (v_topic_id, '11: What is the defining characteristic of "compensated shock" in a pediatric patient?', '["Hypotension", "Normal blood pressure with signs of poor tissue perfusion (e.g., delayed capillary refill, tachycardia)", "Tachycardia only", "Low urine output only"]', 1, 'Compensated shock is defined by normal systolic blood pressure despite signs of inadequate organ perfusion. Hypotension is a late and ominous sign (decompensated shock) in children. (PALS Guidelines)'),
    (v_topic_id, '12: An 8-year-old child with a history of severe peanut allergy is brought to the ER with hives, lip swelling, and wheezing after accidental ingestion. What is the first-line treatment?', '["Intravenous Diphenhydramine", "Nebulized Albuterol", "Intramuscular Epinephrine (0.01 mg/kg of 1:1000)", "Intravenous Methylprednisolone"]', 2, 'IM Epinephrine in the lateral thigh is the immediate first-line treatment for anaphylaxis. (PALS Guidelines)'),
    (v_topic_id, '13: A 5-year-old child with severe dehydration from gastroenteritis is in shock. What is the recommended initial fluid bolus?', '["20 mL/kg of Normal Saline or Lactated Ringer''s", "10 mL/kg of 5% Dextrose", "20 mL/kg of 0.45% Saline", "5 mL/kg of Albumin"]', 0, 'Isotonic crystalloids (NS or LR) at 20 mL/kg are the standard for pediatric volume resuscitation. (PALS Guidelines)'),
    (v_topic_id, '14: A child presents with warm, flushed skin, brisk capillary refill, and a wide pulse pressure (bounding pulses) in the setting of a suspected infection. What type of shock is this?', '["Hypovolemic", "Cardiogenic", "Distributive (Early Septic Shock)", "Obstructive"]', 2, 'Early septic shock (warm shock) involves vasodilation and increased cardiac output, leading to "flash" capillary refill and bounding pulses. (Nelson Essentials)'),
    (v_topic_id, '15: A 12-year-old with a heart rate of 220 bpm and a narrow-complex QRS on ECG is pale and lethargic with a BP of 70/40. What is the most appropriate initial management?', '["Vagal maneuvers", "Adenosine 0.1 mg/kg IV", "Synchronized cardioversion 0.5-1 J/kg", "Amiodarone 5 mg/kg IV"]', 2, 'SVT with hemodynamic instability (shock/altered mental status) requires immediate synchronized cardioversion. If stable, Adenosine or vagal maneuvers can be tried first. (PALS Guidelines)'),
    (v_topic_id, '16: During cardiac arrest, what is the initial energy dose for defibrillation of a shockable rhythm (VF/pulseless VT)?', '["2 J/kg", "4 J/kg", "10 J/kg", "100 Joules"]', 0, 'The initial dose for defibrillation in children is 2 J/kg. Subsequent doses are 4 J/kg, and can be increased up to 10 J/kg. (PALS Guidelines)'),
    (v_topic_id, '17: A child is in cardiac arrest with asystole. After starting high-quality CPR and administering oxygen, what is the first-line medication to be given?', '["Amiodarone", "Atropine", "Epinephrine", "Lidocaine"]', 2, 'Epinephrine (0.01 mg/kg of 1:10,000) is the vasopressor of choice for non-shockable rhythms (asystole/PEA) and should be given as soon as possible. (PALS Guidelines)'),
    (v_topic_id, '18: What is the dose of IV/IO Epinephrine used during pediatric advanced life support for cardiac arrest?', '["0.1 mg/kg of 1:1,000", "0.01 mg/kg of 1:10,000 (0.1 mL/kg)", "1 mg total", "0.01 mg/kg of 1:1,000"]', 1, 'The standard IV/IO dose is 0.01 mg/kg using the 1:10,000 concentration (0.1 mL/kg). (PALS Guidelines)'),
    (v_topic_id, '19: A child in VF arrest remains in VF after two shocks and one dose of epinephrine. Which antiarrhythmic is recommended for refractory shockable rhythms?', '["Adenosine", "Amiodarone (5 mg/kg) or Lidocaine (1 mg/kg)", "Atropine", "Magnesium"]', 1, 'Amiodarone or Lidocaine can be used for shock-refractory VF or pulseless VT. (PALS Guidelines)'),
    (v_topic_id, '20: In a child with bradycardia and a pulse, at what heart rate threshold should you begin chest compressions if there is signs of poor perfusion?', '["< 100 bpm", "< 80 bpm", "< 60 bpm", "< 40 bpm"]', 2, 'PALS guidelines recommend starting CPR for bradycardia with a pulse if the HR is < 60 bpm and signs of poor perfusion persist despite oxygenation and ventilation. (PALS Guidelines)'),
    (v_topic_id, '21: A child presents with sudden onset of lethargy and a heart rate of 250 bpm. The ECG shows a narrow-complex tachycardia with no visible P waves. The rhythm is extremely regular. Diagnosis?', '["Sinus Tachycardia", "Supraventricular Tachycardia (SVT)", "Ventricular Tachycardia", "Atrial Fibrillation"]', 1, 'SVT in children is usually > 220 bpm (infants) or > 180 bpm (children), has no P waves, and a very fixed, regular rate. (Nelson Essentials)'),
    (v_topic_id, '22: Which of the following is a reversible cause of PEA (Pulseless Electrical Activity) represented by the "H''s and T''s"?', '["Hyperglycemia", "Hypovolemia", "Hypernatremia", "Tachycardia"]', 1, 'Hypovolemia is one of the classic "H''s" (Hypovolemia, Hypoxia, Hydrogen ion/acidosis, Hypo/Hyperkalemia, Hypothermia). (PALS Guidelines)'),
    (v_topic_id, '23: A 2-year-old child is brought to the ER after ingesting an unknown amount of his grandmother''s iron supplements. What is the specific antidote for severe iron poisoning?', '["N-acetylcysteine", "Deferoxamine", "Atropine", "Digoxin Immune Fab"]', 1, 'Deferoxamine is the chelating agent used for systemic iron toxicity. (BRS Pediatrics)'),
    (v_topic_id, '24: A child presents with vomiting, abdominal pain, and "rice water" diarrhea. He appears extremely dehydrated. Physical exam shows a "sunken fontanelle" and delayed capillary refill. What is the first priority?', '["Stool culture", "Abdominal X-ray", "Aggressive isotonic fluid resuscitation (20 mL/kg boluses)", "Oral rehydration therapy"]', 2, 'Shock/severe dehydration requires immediate IV volume expansion with isotonic crystalloids. (Blueprints Pediatrics)'),
    (v_topic_id, '25: A 3-year-old girl is found with an open bottle of acetaminophen. The mother is unsure of the timing or amount. What is the most appropriate next step?', '["Immediate gastric lavage", "Check a 4-hour serum acetaminophen level and consult the Rumack-Matthew nomogram", "Administer N-acetylcysteine immediately without waiting for levels", "Induce emesis with Ipecac syrup"]', 1, 'The 4-hour level is the standard for determining the risk of hepatotoxicity and the need for N-acetylcysteine (NAC). (Case Files Pediatrics)'),
    (v_topic_id, '26: A child presents with pinpoint pupils, respiratory depression, and bradycardia. What ingestion do you suspect and what is the antidote?', '["Organophosphates; Pralidoxime", "Opioids; Naloxone", "Benzodiazepines; Flumazenil", "Tricyclic Antidepressants; Sodium Bicarbonate"]', 1, 'The "opioid triad" includes miosis, respiratory depression, and altered mental status. Naloxone is the treatment. (Nelson Essentials)'),
    (v_topic_id, '27: A child presents with salivation, lacrimation, urination, defecation, and pinpoint pupils (SLUDGE mnemonic). What is the mechanism of this toxicity?', '["Anticholinergic blockade", "Cholinergic excess (Acetylcholinesterase inhibition)", "Sympathetic overstimulation", "Serotonin syndrome"]', 1, 'Organophosphate or carbamate poisoning inhibits acetylcholinesterase, leading to a cholinergic crisis. (Nelson Essentials)'),
    (v_topic_id, '28: What is the primary treatment for the bradycardia and excessive secretions in organophosphate poisoning?', '["Naloxone", "Atropine (in high doses)", "Epinephrine", "Diphenhydramine"]', 1, 'Atropine competitively blocks muscarinic receptors, drying secretions and increasing heart rate. (BRS Pediatrics)'),
    (v_topic_id, '29: A 15-year-old is brought to the ER after a suspected overdose. He is confused, has dry/flushed skin, dilated pupils, and urinary retention. What toxidrome is this?', '["Sympathomimetic", "Anticholinergic", "Opioid", "Cholinergic"]', 1, 'Anticholinergic: "Mad as a hatter, red as a beet, dry as a bone, blind as a bat, hot as a hare." (Case Files Pediatrics)'),
    (v_topic_id, '30: Which medication is used to reverse life-threatening anticholinergic toxicity (e.g., severe agitation/seizures from diphenhydramine or Jimson weed)?', '["Atropine", "Physostigmine", "Naloxone", "Flumazenil"]', 1, 'Physostigmine is a reversible acetylcholinesterase inhibitor that crosses the blood-brain barrier. (Nelson Essentials)'),
    (v_topic_id, '31: A 10-year-old child presents with a high-output, wide-complex tachycardia and hypotension. The mother takes amitriptyline (a TCA). What is the first-line pharmacological treatment for TCA-induced QRS widening?', '["Lidocaine", "Sodium Bicarbonate", "Amiodarone", "Magnesium Sulfate"]', 1, 'Sodium bicarbonate (1-2 mEq/kg) alkalinizes the blood and increases the sodium gradient, helping to overcome the sodium channel blockade caused by TCAs. (Nelson Essentials)'),
    (v_topic_id, '32: A 2-year-old child presents with a "burning" throat, drooling, and refusal to drink after swallowing a drain cleaner (alkaline corrosive). What is the contraindicated management?', '["Fiberoptic endoscopy within 24 hours", "Inducing emesis or attempting to neutralize with acid", "Intravenous fluids", "Keeping the child NPO"]', 1, 'Neutralization or emesis increases the risk of further esophageal injury or perforation. Endoscopy is used to grade the injury. (BRS Pediatrics)'),
    (v_topic_id, '33: A child is brought in after being found in a garage with a running car. He is lethargic and complains of a headache. Pulse oximetry is 99% on room air. What is the most likely diagnosis?', '["Opioid overdose", "Carbon monoxide poisoning", "Hypoglycemia", "Cyanide poisoning"]', 1, 'Carbon monoxide (CO) binds to hemoglobin with high affinity. Standard pulse oximetry cannot distinguish carboxyhemoglobin from oxyhemoglobin and will be falsely normal. (Nelson Essentials)'),
    (v_topic_id, '34: What is the treatment for carbon monoxide poisoning?', '["100% Oxygen via non-rebreather mask (or hyperbaric oxygen in severe cases)", "Naloxone", "Nitraglycerin", "Methylene blue"]', 0, '100% oxygen displaces CO from hemoglobin much faster than room air. (BRS Pediatrics)'),
    (v_topic_id, '35: A child presents with cyanosis that does not improve with oxygen. The blood appears "chocolate-colored." He was recently treated with benzocaine for a toothache. Diagnosis?', '["Carbon monoxide poisoning", "Methemoglobinemia", "Iron poisoning", "Cyanide poisoning"]', 1, 'Benzocaine and sulfonamides can cause methemoglobinemia. Chocolate-colored blood and "pulse-ox gap" (low SpO2 but normal PaO2) are clues. (Nelson Essentials)'),
    (v_topic_id, '36: What is the antidote for severe, symptomatic methemoglobinemia?', '["N-acetylcysteine", "Methylene blue", "Oxygen", "Vitamin K"]', 1, 'Methylene blue acts as an electron donor to reduce ferric iron (Fe3+) back to ferrous iron (Fe2+). (Nelson Essentials)'),
    (v_topic_id, '37: A child presents with a fever of 40 C, stiff neck, and a rapidly spreading petechial/purpuric rash. What is the most likely causative organism?', '["Streptococcus pneumoniae", "Neisseria meningitidis", "Haemophilus influenzae", "Staphylococcus aureus"]', 1, 'Meningococcemia is a classic cause of rapid-onset sepsis and petechial rash (purpura fulminans). (Blueprints Pediatrics)'),
    (v_topic_id, '38: In a child with suspected meningococcemia and shock, what is the most important initial management?', '["Perform a lumbar puncture immediately", "Aggressive fluid resuscitation and empiric IV antibiotics (e.g., Ceftriaxone) as soon as possible", "Obtain a CT head", "Start steroids"]', 1, 'Antibiotics should not be delayed for a lumbar puncture if the child is unstable or in shock. (Nelson Essentials)'),
    (v_topic_id, '39: A 2-year-old child presents with a "sudden" generalized tonic-clonic seizure lasting 2 minutes during a fever of 39.5 C. He is now back to his baseline mental status. Diagnosis?', '["Epilepsy", "Simple Febrile Seizure", "Complex Febrile Seizure", "Meningitis"]', 1, 'Simple febrile seizures are generalized, last < 15 minutes, and occur once in 24 hours in a child with a fever and no CNS infection. (Nelson Essentials)'),
    (v_topic_id, '40: What is the management of a first-time simple febrile seizure?', '["Start daily phenobarbital", "Perform an urgent CT scan", "Reassurance and antipyretics for comfort", "Start IV Lorazepam"]', 2, 'Simple febrile seizures are benign and do not require long-term anticonvulsants or aggressive imaging. (Nelson Essentials)'),
    (v_topic_id, '41: A child has been seizing for 10 minutes without stopping. What is the definition and initial drug of choice?', '["Epilepsy; Carbamazepine", "Status Epilepticus; Benzodiazepines (e.g., Lorazepam or Midazolam)", "Febrile seizure; Acetaminophen", "Absence seizure; Ethosuximide"]', 1, 'Status epilepticus is defined as a seizure > 5 minutes. IV/IM Benzodiazepines are first-line. (PALS Guidelines)'),
    (v_topic_id, '42: Which of the following is the most sensitive early indicator of shock in an infant?', '["Hypotension", "Tachycardia", "Decreased urine output", "Cold extremities"]', 1, 'Tachycardia is often the first sign of compensation for decreased stroke volume in pediatric shock. (PALS Guidelines)'),
    (v_topic_id, '43: An 18-month-old child presents with a 2-day history of low-grade fever and a "seal-like" barking cough. The symptoms are worse at night. Diagnosis?', '["Epiglottitis", "Laryngotracheobronchitis (Croup)", "Bacterial tracheitis", "Foreign body aspiration"]', 1, 'Croup typically presents in infants/toddlers with a viral prodrome and a barky cough. (Nelson Essentials)'),
    (v_topic_id, '44: A 4-year-old child presents with high fever, toxic appearance, and thick "purulent" secretions from the trachea. He was being treated for croup but is now worsening. Diagnosis?', '["Epiglottitis", "Bacterial Tracheitis", "Asthma", "Pneumonia"]', 1, 'Bacterial tracheitis is a "pseudo-membranous" infection (often S. aureus) that can mimic croup but is much more severe and toxic-appearing. (Nelson Essentials)'),
    (v_topic_id, '45: A child has an SPO2 of 88% while on a 10L non-rebreather mask. What is the most appropriate next step in oxygen delivery?', '["Increase oxygen to 15L", "Switch to a nasal cannula", "Provide Positive Pressure Ventilation (e.g., CPAP, BiPAP, or Bag-mask)", "Observation"]', 2, 'Failure to maintain oxygenation despite high-flow oxygen is an indication for positive pressure support or intubation. (PALS Guidelines)'),
    (v_topic_id, '46: In a child with a suspected head injury, you notice a "Cushing Triad." What are the components of this triad?', '["Hypertension, Bradycardia, and Irregular respirations", "Hypotension, Tachycardia, and Tachypnea", "Fever, Rash, and Neck stiffness", "Miosis, Ptosis, and Anhydrosis"]', 0, 'Cushing triad indicates significantly increased intracranial pressure (ICP) and impending herniation. (Nelson Essentials)'),
    (v_topic_id, '47: What is the most appropriate immediate intervention to acutely lower ICP in a child with signs of herniation?', '["Aggressive fluid bolus", "Controlled hyperventilation (to PaCO2 30-35) and Mannitol/Hypertonic saline", "Broad-spectrum antibiotics", "Morphine"]', 1, 'Hyperventilation causes cerebral vasoconstriction, reducing cerebral blood volume. Osmotic agents like Mannitol pull fluid out of brain tissue. (Nelson Essentials)'),
    (v_topic_id, '48: A child presents with "currant jelly" stools, intermittent colicky abdominal pain, and a "sausage-shaped" mass in the right upper quadrant. Diagnosis?', '["Appendicitis", "Intussusception", "Volvulus", "Pyloric stenosis"]', 1, 'Intussusception is the telescoping of bowel. Currant jelly stools (blood and mucus) are a classic late finding. (Nelson Essentials)'),
    (v_topic_id, '49: What is both the diagnostic and therapeutic procedure of choice for stable intussusception?', '["Abdominal CT", "Air or Contrast (Barium) enema", "Laparoscopy", "Upper GI series"]', 1, 'Hydrostatic or pneumatic pressure from an enema can often reduce the intussusception. (Blueprints Pediatrics)'),
    (v_topic_id, '50: A 6-year-old boy presents with sudden-onset, severe scrotal pain and an absent cremasteric reflex. The testis is high-riding and transverse. Diagnosis?', '["Epididymitis", "Testicular Torsion", "Hydrocele", "Inguinal hernia"]', 1, 'Testicular torsion is a surgical emergency. The absent cremasteric reflex is a highly sensitive finding. (Nelson Essentials)'),
    (v_topic_id, '51: What is the "golden period" (timeframe) to perform detorsion of the testis to ensure maximal salvage?', '["Within 24 hours", "Within 6 hours", "Within 12 hours", "Within 48 hours"]', 1, 'Testicular viability drops significantly after 6 hours of ischemia. (Nelson Essentials)'),
    (v_topic_id, '52: A child presents with acute-onset abdominal pain starting in the periumbilical area and migrating to the right lower quadrant. He has "rebound tenderness." Diagnosis?', '["Gastroenteritis", "Appendicitis", "Intussusception", "Meckel diverticulum"]', 1, 'Classic presentation of acute appendicitis. (Nelson Essentials)'),
    (v_topic_id, '53: A 2-year-old child presents with "painless" large-volume rectal bleeding (maroon/bright red). He is hemodynamically stable. What is the most likely diagnosis?', '["Intussusception", "Meckel Diverticulum", "Anal fissure", "Inflammatory Bowel Disease"]', 1, 'Meckel diverticulum (ectopic gastric mucosa causing ulceration) is the most common cause of painless lower GI bleeding in this age group. (BRS Pediatrics)'),
    (v_topic_id, '54: What is the diagnostic test for Meckel Diverticulum?', '["Barium enema", "Meckel Scan (Technetium-99m pertechnetate scan)", "Colonoscopy", "Abdominal X-ray"]', 1, 'The pertechnetate is taken up by the ectopic gastric mucosa. (Blueprints Pediatrics)'),
    (v_topic_id, '55: A child is brought to the ER after a near-drowning in a cold lake. He is apneic and pulseless. What is the core principle of resuscitating a hypothermic patient?', '["Stop CPR after 20 minutes", "You are not dead until you are warm and dead (rewarm to 30-32 C before declaring death)", "Use only cold fluids", "Avoid chest compressions"]', 1, 'Hypothermia is neuroprotective. Resuscitation should continue until the patient is rewarmed to at least 30-32 C. (PALS Guidelines)'),
    (v_topic_id, '56: A child presents with multiple bruises in various stages of healing, a fractured femur in a non-ambulatory infant, and retinal hemorrhages. What do you suspect?', '["Osteogenesis imperfecta", "Child Abuse (Non-accidental trauma)", "Leukemia", "Coagulopathy"]', 1, 'A combination of incompatible injury history, injuries of different ages, and specific patterns (e.g., retinal hemorrhages in Shaken Baby Syndrome) are red flags for abuse. (Nelson Essentials)'),
    (v_topic_id, '57: What is your legal obligation when you suspect child abuse?', '["Only report if you have absolute proof", "Report your suspicions to Child Protective Services (CPS) or local authorities immediately", "Ask the parents for a confession first", "Wait for the social worker to decide"]', 1, 'All healthcare providers are "mandated reporters." You must report suspected abuse; you do not need proof. (Nelson Essentials)'),
    (v_topic_id, '58: A child presents with high fever, "hot potato" voice, and the uvula is deviated to the left. The right tonsil is bulging. Diagnosis?', '["Retropharyngeal abscess", "Peritonsillar abscess", "Epiglottitis", "Strep throat"]', 1, 'Peritonsillar abscess (Quinsy) typically presents with uvular deviation and trismus. (BRS Pediatrics)'),
    (v_topic_id, '59: A child presents with fever, neck stiffness, and refusal to move the neck. A lateral neck X-ray shows widening of the prevertebral space. Diagnosis?', '["Peritonsillar abscess", "Retropharyngeal abscess", "Meningitis", "Torticollis"]', 1, 'Retropharyngeal abscess is located in the space behind the pharynx and can cause airway compromise. (Nelson Essentials)'),
    (v_topic_id, '60: Which of the following is the most common cause of "obstructive shock" in a pediatric trauma patient?', '["Hemorrhage", "Tension Pneumothorax", "Spinal cord injury", "Sepsis"]', 1, 'Tension pneumothorax and cardiac tamponade are the classic causes of obstructive shock in trauma. (PALS Guidelines)'),
    (v_topic_id, '61: A child with a tension pneumothorax should undergo immediate needle decompression. Where is the preferred anatomical site?', '["2nd intercostal space, midclavicular line", "5th intercostal space, midaxillary line", "9th intercostal space, posterior", "None of the above"]', 0, 'This is the standard site for emergency needle decompression of the pleural space. (PALS Guidelines)'),
    (v_topic_id, '62: A child presents with a "muffled" heart sounds, distended neck veins, and hypotension (Beck''s triad). Diagnosis?', '["Tension pneumothorax", "Cardiac Tamponade", "Hypovolemic shock", "Myocardial contusion"]', 1, 'Cardiac tamponade prevents the heart from filling properly, leading to obstructive shock. (Nelson Essentials)'),
    (v_topic_id, '63: What is the primary treatment for cardiac tamponade?', '["IV Fluids", "Pericardiocentesis", "Needle thoracostomy", "Epinephrine"]', 1, 'Removal of the fluid from the pericardial sac is life-saving. (Nelson Essentials)'),
    (v_topic_id, '64: A 10-year-old child presents with severe polyuria, polydipsia, and "fruity" breath. He is lethargic and breathing deeply/rapidly (Kussmaul breathing). Diagnosis?', '["Diabetes Insipidus", "Diabetic Ketoacidosis (DKA)", "Hypoglycemia", "Sepsis"]', 1, 'DKA is a metabolic emergency characterized by hyperglycemia, ketosis, and acidosis. (Nelson Essentials)'),
    (v_topic_id, '65: What is the most serious and common cause of mortality in children being treated for DKA?', '["Hypoglycemia", "Cerebral Edema", "Hypokalemia", "Aspiration pneumonia"]', 1, 'Rapid fluid shifts can lead to cerebral edema, which is why fluids must be replaced slowly and carefully. (Nelson Essentials)'),
    (v_topic_id, '66: A child presents with hypoglycemia (glucose < 40 mg/dL) and altered mental status. What is the recommended dose of IV Dextrose?', '["2-4 mL/kg of D10W (10% Dextrose)", "1 mL/kg of D50W", "10 mL/kg of D5W", "0.5 mg Glucagon"]', 0, 'D10W (10% Dextrose) is the preferred concentration for infants and children to avoid hypertonicity and venous injury. (PALS Guidelines)'),
    (v_topic_id, '67: A child is brought in with a "button battery" lodged in the mid-esophagus. What is the appropriate management?', '["Check a follow-up X-ray in 24 hours", "Immediate endoscopic removal", "Give the child a drink to help it pass", "Observe for symptoms"]', 1, 'Button batteries in the esophagus are an emergency as they can cause rapid liquefactive necrosis and perforation. (Nelson Essentials)'),
    (v_topic_id, '68: A child presents with sudden onset of high fever and "purpuric" lesions. He is diagnosed with Waterhouse-Friderichsen syndrome. This involves hemorrhage into which organ?', '["Liver", "Adrenal Glands", "Kidneys", "Brain"]', 1, 'Waterhouse-Friderichsen is adrenal insufficiency caused by massive hemorrhage into the adrenal glands, typically during meningococcemia. (Nelson Essentials)'),
    (v_topic_id, '69: A 6-month-old infant is found face down in the crib, pulseless. This is categorized as SIDS (Sudden Infant Death Syndrome) if what condition is met?', '["The infant had a cold", "The death remains unexplained after a thorough investigation, including autopsy", "The infant was sleeping on his back", "The mother smoked"]', 1, 'SIDS is a diagnosis of exclusion for infants < 1 year. (Nelson Essentials)'),
    (v_topic_id, '70: What is the most important "safe sleep" recommendation to prevent SIDS?', '["Sleep on the stomach", "Sleep on the back on a firm surface without soft bedding (Back to Sleep)", "Sleep in the same bed as parents", "Use a bumper pad in the crib"]', 1, 'The "Back to Sleep" campaign has significantly reduced SIDS rates. (Nelson Essentials)'),
    (v_topic_id, '71: What is the most common cause of painless, massive lower GI bleeding in a 2-year-old child?', '["Intussusception", "Meckel Diverticulum", "Anal fissure", "Juvenile polyps"]', 1, 'Meckel diverticulum is the most common cause of painless lower GI bleeding in toddlers. It is caused by ectopic gastric mucosa. (Nelson Essentials)'),
    (v_topic_id, '72: A 3-year-old child presents with sudden-onset wheezing and decreased breath sounds on the right side. The child was previously healthy and playing with blocks. Diagnosis?', '["Asthma", "Bronchiolitis", "Foreign Body Aspiration", "Pneumonia"]', 2, 'Sudden, focal wheezing in a toddler is highly suspicious for foreign body aspiration. (Case Files Pediatrics)'),
    (v_topic_id, '73: What is the primary treatment for a "button battery" lodged in the esophagus?', '["Observe for 24 hours", "Give laxatives", "Immediate endoscopic removal", "Wait for it to pass into the stomach"]', 2, 'Button batteries in the esophagus are a surgical emergency due to the risk of rapid electrical and chemical injury. (Nelson Essentials)'),
    (v_topic_id, '74: A 5-year-old presents with high fever, sore throat, and a "muffled" voice. He is sitting in a tripod position. What is the most dangerous diagnostic maneuver?', '["Lateral neck X-ray", "Examining the throat with a tongue blade", "Pulse oximetry", "Blood cultures"]', 1, 'In suspected epiglottitis, examining the throat can trigger laryngospasm and complete airway obstruction. (BRS Pediatrics)'),
    (v_topic_id, '75: A 10-year-old child is hit by a car. He is unconscious with a dilated right pupil and left-sided hemiparesis. What is the most likely diagnosis?', '["Concussion", "Uncal Herniation", "Diffuse Axonal Injury", "Basilar Skull Fracture"]', 1, 'Ipsilateral pupil dilation and contralateral hemiparesis are classic signs of uncal herniation from increased ICP. (Nelson Essentials)'),
    (v_topic_id, '76: In the management of pediatric status epilepticus, which medication is typically given as a second-line agent if benzodiazepines fail?', '["Phenobarbital", "Fosphenytoin or Levetiracetam", "Propofol", "Ethosuximide"]', 1, 'Fosphenytoin, Levetiracetam, or Valproic acid are standard second-line anti-seizure medications in PALS algorithms. (PALS Guidelines)'),
    (v_topic_id, '77: A child presents with "cherry-red" skin and mucous membranes after being rescued from a house fire. What toxicity do you suspect?', '["Cyanide", "Carbon Monoxide", "Lead", "Organophosphates"]', 1, 'Carbon monoxide poisoning classically causes cherry-red skin, though this is often a late or post-mortem finding. (Blueprints Pediatrics)'),
    (v_topic_id, '78: What is the recommended treatment for a child with symptomatic lead poisoning (level > 45 mcg/dL)?', '["Deferoxamine", "Succimer (DMSA)", "N-acetylcysteine", "Atropine"]', 1, 'Succimer is the preferred oral chelating agent for lead levels between 45 and 69 mcg/dL. (Nelson Essentials)'),
    (v_topic_id, '79: A child presents with vomiting, diarrhea, and a "garlic" odor on his breath after playing in an old shed. Diagnosis?', '["Iron poisoning", "Arsenic poisoning", "Lead poisoning", "Mercury poisoning"]', 1, 'Arsenic toxicity classically presents with a garlic-like odor and severe GI symptoms. (BRS Pediatrics)'),
    (v_topic_id, '80: A 12-year-old is brought to the ER with a heart rate of 190 bpm, QRS duration of 0.14 seconds, and AV dissociation. Diagnosis?', '["Supraventricular Tachycardia (SVT)", "Ventricular Tachycardia (VT)", "Sinus Tachycardia", "Atrial Fibrillation"]', 1, 'Wide-complex tachycardia (> 0.09s in infants, > 0.12s in children) with AV dissociation is Ventricular Tachycardia. (PALS Guidelines)'),
    (v_topic_id, '81: What is the initial energy dose for synchronized cardioversion in a child with unstable SVT?', '["0.5 to 1.0 J/kg", "2.0 J/kg", "4.0 J/kg", "10.0 J/kg"]', 0, 'Synchronized cardioversion starts at 0.5-1.0 J/kg. (PALS Guidelines)'),
    (v_topic_id, '82: A child presents with "barky" cough and inspiratory stridor. X-ray shows the "steeple sign." Diagnosis?', '["Epiglottitis", "Croup", "Foreign body", "Bacterial tracheitis"]', 1, 'The steeple sign (subglottic narrowing) is characteristic of Croup. (Blueprints Pediatrics)'),
    (v_topic_id, '83: A 4-year-old child presents with high fever, "hot potato" voice, and drooling. X-ray shows the "thumbprint sign." Diagnosis?', '["Croup", "Epiglottitis", "Bronchiolitis", "Pneumonia"]', 1, 'The thumbprint sign (swollen epiglottis) is characteristic of Epiglottitis. (Nelson Essentials)'),
    (v_topic_id, '84: In a child with septic shock, which vasoactive agent is preferred for "cold" shock (low CO, high SVR)?', '["Norepinephrine", "Epinephrine", "Dopamine", "Phenylephrine"]', 1, 'Epinephrine is often preferred in pediatric cold shock to increase heart rate and contractility. (PALS Guidelines)'),
    (v_topic_id, '85: Which vasoactive agent is preferred for "warm" shock (high CO, low SVR)?', '["Epinephrine", "Norepinephrine", "Dobutamine", "Milrinone"]', 1, 'Norepinephrine is preferred for warm shock to increase systemic vascular resistance. (PALS Guidelines)'),
    (v_topic_id, '86: A child presents with polyuria, polydipsia, and a glucose of 500 mg/dL. He is breathing rapidly. What is the most appropriate initial fluid therapy?', '["20 mL/kg bolus of NS over 10 minutes", "10-20 mL/kg bolus of NS over 1-2 hours (careful rehydration)", "5% Dextrose bolus", "Insulin bolus immediately"]', 1, 'In DKA, aggressive boluses are avoided unless the patient is in frank shock to reduce the risk of cerebral edema. (Nelson Essentials)'),
    (v_topic_id, '87: When treating DKA, when should potassium be added to the IV fluids?', '["Immediately", "Once urine output is confirmed and K+ is not high", "Only if K+ is < 3.0", "Never"]', 1, 'Potassium levels drop quickly once insulin is started; early replacement (after confirming renal function) is vital. (Nelson Essentials)'),
    (v_topic_id, '88: A child presents with periorbital bruising ("raccoon eyes") and clear fluid leaking from the nose after a fall. Diagnosis?', '["Concussion", "Basilar Skull Fracture", "Nasal fracture", "Orbital cellulitis"]', 1, 'Raccoon eyes and rhinorrhea (CSF leak) are classic signs of a basilar skull fracture. (BRS Pediatrics)'),
    (v_topic_id, '89: What is the most common type of pediatric fracture caused by a "fall on an outstretched hand" (FOOSH)?', '["Mid-shaft humerus", "Supracondylar humerus fracture", "Clavicle fracture", "Scaphoid fracture"]', 1, 'Supracondylar fractures are very common in children and carry a risk of brachial artery injury. (Case Files Pediatrics)'),
    (v_topic_id, '90: A child with a supracondylar fracture has severe pain on passive extension of the fingers and a weak radial pulse. What do you suspect?', '["Radial nerve palsy", "Compartment Syndrome (Volkmann ischemic contracture)", "Normal healing pain", "Dislocation"]', 1, 'Pain out of proportion and pain with passive stretch are early signs of compartment syndrome. (Nelson Essentials)'),
    (v_topic_id, '91: A 14-year-old boy presents with sudden-onset, severe testicular pain and a "blue dot sign" on the upper pole of the testis. The cremasteric reflex is present. Diagnosis?', '["Testicular Torsion", "Torsion of the Appendix Testis", "Epididymitis", "Hydrocele"]', 1, 'The "blue dot sign" and presence of the cremasteric reflex distinguish appendix testis torsion from true testicular torsion. (Nelson Essentials)'),
    (v_topic_id, '92: A 2-year-old is brought to the ER with a "pulled elbow." He refuses to use the arm and keeps it pronated. What is the maneuver to reduce this "Nursemaid''s Elbow"?', '["Hyperpronation or Supination and flexion", "Traction and abduction", "Cast for 2 weeks", "Open reduction"]', 0, 'Nursemaid''s elbow (subluxation of the radial head) is reduced by hyperpronation or supination-flexion maneuvers. (Blueprints Pediatrics)'),
    (v_topic_id, '93: What is the most appropriate first-line treatment for a child with a large, non-tension pneumothorax?', '["Needle decompression", "Chest tube (tube thoracostomy)", "Observation", "High-flow oxygen"]', 1, 'Stable but large pneumothoraces require chest tube drainage. (BRS Pediatrics)'),
    (v_topic_id, '94: A child is found in a swimming pool, unresponsive. After 2 minutes of CPR, he has a pulse but remains apneic. What is the goal of rescue breathing for this child?', '["10-12 breaths/min", "20-30 breaths/min", "60 breaths/min", "1 breath every 10 seconds"]', 1, 'As per updated PALS, the rescue breathing rate for children/infants is 1 breath every 2-3 seconds. (PALS Guidelines)'),
    (v_topic_id, '95: A child presents with a "staccato" cough, no fever, and a history of maternal chlamydia infection at birth. Diagnosis?', '["Bronchiolitis", "Chlamydia Pneumonia", "Pertussis", "Croup"]', 1, 'Chlamydia trachomatis pneumonia in infants typically presents at 1-3 months with a staccato cough and peripheral eosinophilia. (Nelson Essentials)'),
    (v_topic_id, '96: A 2-month-old presents with paroxysms of coughing followed by an inspiratory "whoop" and post-tussive emesis. Diagnosis?', '["Asthma", "Pertussis", "Bronchiolitis", "Croup"]', 1, 'Pertussis (Whooping Cough) is a serious illness in infants, who may present with apnea rather than a whoop. (Nelson Essentials)'),
    (v_topic_id, '97: What is the first-line antibiotic treatment for a child with Pertussis (to reduce transmission)?', '["Amoxicillin", "Azithromycin", "Ceftriaxone", "Vancomycin"]', 1, 'Macrolides like Azithromycin are the treatment of choice. (Blueprints Pediatrics)'),
    (v_topic_id, '98: A child presents with a "muffled" voice, drooling, and a significant "bulge" in the posterior pharyngeal wall. Diagnosis?', '["Peritonsillar abscess", "Retropharyngeal abscess", "Epiglottitis", "Croup"]', 1, 'Retropharyngeal abscess is more common in younger children (< 6 years). (Nelson Essentials)'),
    (v_topic_id, '99: What is the most common causative agent of bronchiolitis?', '["Parainfluenza", "Respiratory Syncytial Virus (RSV)", "Influenza", "Adenovirus"]', 1, 'RSV is responsible for the majority of bronchiolitis cases. (Nelson Essentials)'),
    (v_topic_id, '100: A child with asthma exacerbation has a "normal" PaCO2 on an ABG despite significant respiratory distress. What does this signify?', '["The child is improving", "Impending respiratory failure", "The child is stable", "Metabolic compensation"]', 1, 'A normal or rising PaCO2 in a tachypneic patient indicates they are tiring and can no longer compensate. (BRS Pediatrics)'),
    (v_topic_id, '101: In a child with status asthmaticus refractory to continuous albuterol and steroids, what is a "next-line" rescue medication?', '["Intravenous Magnesium Sulfate", "Oral Theophylline", "Inhaled Saline", "Antibiotics"]', 0, 'IV Magnesium sulfate causes smooth muscle relaxation and is used in severe asthma. (PALS Guidelines)'),
    (v_topic_id, '102: A child presents with hematuria, periorbital edema, and hypertension 2 weeks after a "sore throat." Diagnosis?', '["Minimal Change Disease", "Post-streptococcal Glomerulonephritis (PSGN)", "IgA Nephropathy", "Henoch-Schonlein Purpura"]', 1, 'PSGN follows a Group A Strep infection (skin or throat). (Nelson Essentials)'),
    (v_topic_id, '103: A child presents with palpable purpura on the buttocks/legs, joint pain, and abdominal pain. Diagnosis?', '["ITP", "Henoch-Schonlein Purpura (HSP)", "Meningococcemia", "Hemophilia"]', 1, 'HSP is an IgA-mediated small vessel vasculitis. (Nelson Essentials)'),
    (v_topic_id, '104: What is the most common serious gastrointestinal complication of Henoch-Schonlein Purpura?', '["Appendicitis", "Intussusception (ileo-ileal)", "Volvulus", "Gastritis"]', 1, 'Bowel wall edema in HSP can act as a lead point for intussusception. (Case Files Pediatrics)'),
    (v_topic_id, '105: A 1-year-old child presents with a high fever for 5 days, strawberry tongue, red eyes (conjunctivitis), and a peeling rash on the hands. Diagnosis?', '["Measles", "Scarlet Fever", "Kawasaki Disease", "Roseola"]', 2, 'Kawasaki disease is a medium-vessel vasculitis of childhood. (Nelson Essentials)'),
    (v_topic_id, '106: What is the most important test to order in a child newly diagnosed with Kawasaki disease?', '["Chest X-ray", "Echocardiogram", "Brain MRI", "Renal Ultrasound"]', 1, 'Echo is needed to screen for coronary artery aneurysms. (Nelson Essentials)'),
    (v_topic_id, '107: What is the standard treatment for Kawasaki disease to prevent coronary artery aneurysms?', '["Steroids", "IVIG and High-dose Aspirin", "Antibiotics", "Acyclovir"]', 1, 'IVIG within the first 10 days significantly reduces the risk of aneurysms. (Blueprints Pediatrics)'),
    (v_topic_id, '108: A child presents with bloody diarrhea followed by acute renal failure, anemia, and thrombocytopenia. Diagnosis?', '["HUS (Hemolytic Uremic Syndrome)", "TTP", "Sepsis", "DIC"]', 0, 'HUS is typically caused by Shiga-toxin producing E. coli (O157:H7). (Nelson Essentials)'),
    (v_topic_id, '109: A child presents with a "swollen" eye, pain with eye movement, and proptosis. Diagnosis?', '["Preseptal cellulitis", "Orbital cellulitis", "Conjunctivitis", "Allergy"]', 1, 'Pain with eye movement and proptosis distinguish orbital from preseptal cellulitis. (Nelson Essentials)'),
    (v_topic_id, '110: A child with a "ventricular shunt" for hydrocephalus presents with headache, vomiting, and lethargy. What is the first priority?', '["Shunt series (X-rays)", "Head CT and Neurosurgery consultation", "Lumbar puncture", "Antibiotics"]', 1, 'Shunt malfunction or infection is a neurosurgical emergency. (BRS Pediatrics)'),
    (v_topic_id, '111: A child presents with a "high-pitched" inspiratory sound only when lying on his back, which improves when prone. Diagnosis?', '["Croup", "Laryngomalacia", "Epiglottitis", "Vascular ring"]', 1, 'Laryngomalacia is the most common cause of congenital stridor. (Nelson Essentials)'),
    (v_topic_id, '112: A 3-month-old infant is brought in with "weakness" and a weak cry after being fed honey. Diagnosis?', '["SMA Type 1", "Infant Botulism", "Myasthenia Gravis", "Sepsis"]', 1, 'Honey can contain Clostridium botulinum spores. (Case Files Pediatrics)'),
    (v_topic_id, '113: What is the treatment for Infant Botulism?', '["Penicillin", "BIG-IV (Botulism Immune Globulin)", "Naloxone", "Supportive care only"]', 1, 'BIG-IV (Human-derived) is the treatment for infant botulism. (Nelson Essentials)'),
    (v_topic_id, '114: A child presents with "paralysis" starting in the legs and moving upwards after a GI illness. Diagnosis?', '["Transverse myelitis", "Guillain-Barre Syndrome (GBS)", "Polio", "Tick paralysis"]', 1, 'GBS is an ascending polyneuropathy often following Campylobacter jejuni infection. (Nelson Essentials)'),
    (v_topic_id, '115: A child is brought in after a "near-miss" SIDS event (briefly turned blue and stopped breathing, but recovered). What is this event called?', '["SIDS", "ALTE (Apparent Life-Threatening Event) or BRUE", "Seizure", "Choking"]', 1, 'BRUE (Brief Resolved Unexplained Event) is the current term. (Nelson Essentials)'),
    (v_topic_id, '116: A child presents with a "painless" swelling in the neck that moves with swallowing. Diagnosis?', '["Branchial cleft cyst", "Thyroglossal duct cyst", "Cystic hygroma", "Lymphadenitis"]', 1, 'Thyroglossal duct cysts are midline and move with the tongue/swallowing. (BRS Pediatrics)'),
    (v_topic_id, '117: A child presents with a swelling anterior to the sternocleidomastoid muscle. Diagnosis?', '["Thyroglossal duct cyst", "Branchial cleft cyst", "Cystic hygroma", "Goiter"]', 1, 'Branchial cleft cysts are located laterally. (Nelson Essentials)'),
    (v_topic_id, '118: A child presents with a large "cystic" mass in the neck present since birth that transilluminates. Diagnosis?', '["Cystic Hygroma (Lymphangioma)", "Thyroid tumor", "Hemangioma", "Abscess"]', 0, 'Cystic hygromas are lymphatic malformations often seen in Turner syndrome. (Blueprints Pediatrics)'),
    (v_topic_id, '119: What is the most common cause of "congenital" hypothyroidism?', '["Iodine deficiency", "Thyroid dysgenesis (aplasia or ectopic gland)", "Maternal antibodies", "TSH deficiency"]', 1, 'Thyroid dysgenesis is the most common cause in developed countries. (Nelson Essentials)'),
    (v_topic_id, '120: A child presents with intellectual disability, a large tongue, and a "hoarse" cry. Diagnosis?', '["Down Syndrome", "Congenital Hypothyroidism (Cretinism)", "Sepsis", "Hurler Syndrome"]', 1, 'Untreated congenital hypothyroidism leads to permanent developmental delay. (Nelson Essentials)'),
    (v_topic_id, '121: What is the screening test for sickle cell anemia in a newborn?', '["Peripheral smear", "Hemoglobin electrophoresis", "Sickle-dex test", "CBC"]', 1, 'Hb electrophoresis is used to detect HbS and other variants. (Nelson Essentials)'),
    (v_topic_id, '122: A child with sickle cell anemia presents with sudden-onset pallor, tachycardia, and a massively enlarged spleen. Diagnosis?', '["Vaso-occlusive crisis", "Splenic Sequestration Crisis", "Aplastic crisis", "Hemolytic crisis"]', 1, 'Splenic sequestration is a life-threatening emergency where blood is trapped in the spleen. (Nelson Essentials)'),
    (v_topic_id, '123: A child with sickle cell anemia presents with a sudden drop in hemoglobin and a "reticulocyte count of 0%." Diagnosis?', '["Splenic sequestration", "Aplastic Crisis (Parvovirus B19)", "Vaso-occlusive crisis", "Hyperhemolytic crisis"]', 1, 'Parvovirus B19 stops RBC production, leading to an aplastic crisis. (Nelson Essentials)'),
    (v_topic_id, '124: A child with sickle cell anemia presents with fever, chest pain, and a "new infiltrate" on chest X-ray. Diagnosis?', '["Pneumonia", "Acute Chest Syndrome", "Pulmonary embolism", "Heart failure"]', 1, 'Acute Chest Syndrome is a leading cause of death in sickle cell disease. (Nelson Essentials)'),
    (v_topic_id, '125: What is the treatment for Acute Chest Syndrome?', '["Antibiotics and Oxygen", "Pain control and IV fluids", "Simple or Exchange Transfusion", "All of the above"]', 3, 'Comprehensive management including transfusion is vital. (Nelson Essentials)'),
    (v_topic_id, '126: A child with sickle cell anemia is at high risk for infection with which type of organisms due to functional asplenia?', '["Gram-negative rods", "Encapsulated organisms (S. pneumoniae, H. influenzae)", "Fungi", "Viruses"]', 1, 'The spleen is needed to clear encapsulated bacteria. (Nelson Essentials)'),
    (v_topic_id, '127: Which medication should all children with sickle cell anemia take daily to prevent pneumococcal sepsis?', '["Aspirin", "Penicillin V prophylaxis", "Hydroxyurea", "Folic acid"]', 1, 'Penicillin prophylaxis is started at birth/diagnosis until at least age 5. (Nelson Essentials)'),
    (v_topic_id, '128: What medication is used to increase fetal hemoglobin (HbF) in patients with sickle cell anemia?', '["Penicillin", "Hydroxyurea", "Iron", "Erythropoietin"]', 1, 'Hydroxyurea increases HbF, which does not sickle. (Nelson Essentials)'),
    (v_topic_id, '129: A child presents with a "painless" abdominal mass and "aniridia" (absence of the iris). Diagnosis?', '["Neuroblastoma", "Wilms Tumor (WAGR syndrome)", "Hepatoblastoma", "Teratoma"]', 1, 'WAGR: Wilms, Aniridia, Genitourinary, Retardation. (Nelson Essentials)'),
    (v_topic_id, '130: A child presents with a "midline" abdominal mass, "raccoon eyes," and opsoclonus-myoclonus. Diagnosis?', '["Wilms Tumor", "Neuroblastoma", "Lymphoma", "Sepsis"]', 1, 'Neuroblastoma is a tumor of the sympathetic chain. (Nelson Essentials)'),
    (v_topic_id, '131: A child presents with a "smooth" abdominal mass that does NOT cross the midline. Diagnosis?', '["Neuroblastoma", "Wilms Tumor", "Hydronephrosis", "Splenomegaly"]', 1, 'Wilms tumor arises from the kidney. (Nelson Essentials)'),
    (v_topic_id, '132: A child presents with severe bone pain, fever, and a "sunburst" pattern on an X-ray of the femur. Diagnosis?', '["Osteosarcoma", "Ewing Sarcoma", "Osteomyelitis", "Growing pains"]', 0, 'Osteosarcoma typically occurs in the metaphysis of long bones. (Nelson Essentials)'),
    (v_topic_id, '133: A child presents with an "onion-skin" appearance on an X-ray of the diaphysis of the humerus. Diagnosis?', '["Osteosarcoma", "Ewing Sarcoma", "Osteomyelitis", "Bone cyst"]', 1, 'Ewing Sarcoma is a small blue cell tumor. (Nelson Essentials)'),
    (v_topic_id, '134: What is the most common primary "brain tumor" in children?', '["Glioblastoma", "Astrocytoma (Pilocytic)", "Medulloblastoma", "Ependymoma"]', 1, 'Pilocytic astrocytoma is common and often has a good prognosis. (Nelson Essentials)'),
    (v_topic_id, '135: A child presents with headache and "morning vomiting" that improves throughout the day. What do you suspect?', '["Gastroenteritis", "Increased Intracranial Pressure (e.g., brain tumor)", "Migraine", "Bulimia"]', 1, 'Morning vomiting is a classic sign of increased ICP. (BRS Pediatrics)'),
    (v_topic_id, '136: A child presents with "pre-auricular" skin tags and pits. Which organ system should you screen for anomalies?', '["Heart", "Kidneys (Renal ultrasound)", "Lungs", "Brain"]', 1, 'Ear anomalies are associated with renal anomalies in several syndromes (e.g., Branchio-oto-renal). (Nelson Essentials)'),
    (v_topic_id, '137: A newborn is noted to have a "clunk" when the hips are abducted (positive Ortolani). Diagnosis?', '["Fracture", "Developmental Dysplasia of the Hip (DDH)", "Slipped capital femoral epiphysis", "Legg-Calve-Perthes"]', 1, 'DDH requires early intervention with a Pavlik harness. (Nelson Essentials)'),
    (v_topic_id, '138: A 12-year-old obese boy presents with a "limp" and hip pain. Diagnosis?', '["Legg-Calve-Perthes", "Slipped Capital Femoral Epiphysis (SCFE)", "Osgood-Schlatter", "Septic arthritis"]', 1, 'SCFE is common in obese adolescents. (Nelson Essentials)'),
    (v_topic_id, '139: A 5-year-old presents with a "painless" limp and hip pain. X-ray shows flattening of the femoral head. Diagnosis?', '["SCFE", "Legg-Calve-Perthes Disease", "Toxic synovitis", "Septic arthritis"]', 1, 'LCP is avascular necrosis of the femoral head in younger children. (Nelson Essentials)'),
    (v_topic_id, '140: A child presents with a limp, hip pain, and a recent "viral illness." He has no fever and a normal WBC. Diagnosis?', '["Septic arthritis", "Transient (Toxic) Synovitis", "Osteomyelitis", "Juvenile Idiopathic Arthritis"]', 1, 'Toxic synovitis is a benign, post-viral inflammation of the hip. (Nelson Essentials)'),
    (v_topic_id, '141: What is the most common cyanotic congenital heart defect presenting in the first 24-48 hours of life?', '["Tetralogy of Fallot", "Transposition of the Great Arteries (TGA)", "Tricuspid Atresia", "Ebstein Anomaly"]', 1, 'TGA is the most common cause of cyanosis in the immediate neonatal period. (Nelson Essentials)'),
    (v_topic_id, '142: A neonate with TGA remains alive only if there is mixing of blood. What life-saving medication is used to keep the ductus arteriosus open?', '["Indomethacin", "Prostaglandin E1 (Alprostadil)", "Epinephrine", "Amiodarone"]', 1, 'PGE1 maintains the patency of the ductus arteriosus. (PALS Guidelines)'),
    (v_topic_id, '143: A child presents with cyanosis and a "boot-shaped" heart on chest X-ray. Diagnosis?', '["TGA", "Tetralogy of Fallot", "Truncus Arteriosus", "Coarctation of the aorta"]', 1, 'The "coeur en sabot" (boot-shaped heart) is due to right ventricular hypertrophy in TOF. (Nelson Essentials)'),
    (v_topic_id, '144: What are the four components of Tetralogy of Fallot?', '["VSD, Overriding aorta, Pulmonary stenosis, RVH", "ASD, VSD, PDA, Coarctation", "Left-to-right shunt, Pulmonary HTN, RVH, Cyanosis", "Aortic stenosis, VSD, RVH, ASD"]', 0, 'TOF: VSD, Overriding Aorta, Pulmonary Stenosis, and Right Ventricular Hypertrophy. (Nelson Essentials)'),
    (v_topic_id, '145: A neonate presents with a "snowman" or "Figure-8" sign on chest X-ray. Diagnosis?', '["TGA", "Total Anomalous Pulmonary Venous Return (TAPVR)", "Tricuspid Atresia", "VSD"]', 1, 'The snowman appearance is seen in supracardiac TAPVR. (Blueprints Pediatrics)'),
    (v_topic_id, '146: What maternal medication is classically associated with Ebstein Anomaly in the neonate?', '["Warfarin", "Lithium", "Valproic acid", "Phenytoin"]', 1, 'Lithium exposure in the first trimester is a known risk factor for Ebstein anomaly. (Nelson Essentials)'),
    (v_topic_id, '147: A neonate with "shock" and metabolic acidosis on day 4 of life (as the ductus closes) should be suspected of having what?', '["Sepsis", "Ductal-dependent systemic lesion (e.g., Coarctation or HLHS)", "Pneumonia", "Hypoglycemia"]', 1, 'Closure of the PDA in critical coarctation or hypoplastic left heart syndrome (HLHS) leads to a sudden drop in systemic perfusion. (PALS Guidelines)'),
    (v_topic_id, '148: A child presents with a continuous, "machine-like" murmur at the left infraclavicular area. Diagnosis?', '["VSD", "ASD", "Patent Ductus Arteriosus (PDA)", "Aortic stenosis"]', 2, 'The PDA murmur is continuous throughout systole and diastole. (Nelson Essentials)'),
    (v_topic_id, '149: What medication is used to close a PDA in a premature infant?', '["Prostaglandin E1", "Indomethacin or Ibuprofen", "Epinephrine", "Dopamine"]', 1, 'Indomethacin is a prostaglandin synthesis inhibitor that promotes PDA closure. (Nelson Essentials)'),
    (v_topic_id, '150: A 2-week-old infant presents with "bilious" vomiting and a midgut volvulus is suspected. What is the definitive diagnostic test?', '["Abdominal X-ray", "Upper GI Series", "Abdominal Ultrasound", "CT scan"]', 1, 'An upper GI series showing the "corkscrew" appearance or abnormal ligament of Treitz position is the gold standard. (Case Files Pediatrics)'),
    (v_topic_id, '151: What is the most common organism causing "osteomyelitis" in children, including those with sickle cell disease?', '["Salmonella", "Staphylococcus aureus", "Group A Strep", "Pseudomonas"]', 1, 'While Salmonella is unique to sickle cell, S. aureus is still the overall most common cause of osteomyelitis in all children. (Nelson Essentials)'),
    (v_topic_id, '152: A child presents with a high fever and a "hot, swollen, painful joint" with limited range of motion. Diagnosis?', '["Osteomyelitis", "Septic Arthritis", "Toxic Synovitis", "Growing pains"]', 1, 'Septic arthritis is a surgical emergency requiring joint aspiration and drainage. (Nelson Essentials)'),
    (v_topic_id, '153: What are the "Kocher criteria" used for?', '["Differentiating septic arthritis from toxic synovitis of the hip", "Diagnosing Kawasaki disease", "Predicting survival in sepsis", "Determining the need for appendectomy"]', 0, 'The 4 criteria are: Fever > 38.5 C, Non-weight bearing, ESR > 40, and WBC > 12,000. (Nelson Essentials)'),
    (v_topic_id, '154: A 10-day-old infant presents with a "punched-out" scalp lesion. Diagnosis?', '["Forceps injury", "Aplasia Cutis Congenita", "Herpes", "Ringworm"]', 1, 'Aplasia cutis congenita is a localized absence of skin, often on the vertex of the scalp. (Blueprints Pediatrics)'),
    (v_topic_id, '155: A newborn male presents with ambiguous genitalia and life-threatening salt-wasting (low Na, high K). What enzyme is most likely deficient?', '["11-beta-hydroxylase", "21-hydroxylase", "17-alpha-hydroxylase", "Aromatase"]', 1, '21-hydroxylase deficiency is the most common cause of Congenital Adrenal Hyperplasia (CAH). (Nelson Essentials)'),
    (v_topic_id, '156: A child presents with profound hypotonia ("floppy baby"), macroglossia, and heart failure. Diagnosis?', '["Down Syndrome", "Pompe Disease (GSD Type II)", "Von Gierke Disease", "SMA Type 1"]', 1, 'Pompe disease involves glycogen accumulation in the lysosomes of the heart and skeletal muscle. (Nelson Essentials)'),
    (v_topic_id, '157: A child presents with a "cherry-red spot" on the macula and hepatosplenomegaly. Diagnosis?', '["Tay-Sachs", "Niemann-Pick Disease", "Gaucher", "Hurler"]', 1, 'Niemann-Pick has hepatosplenomegaly; Tay-Sachs does not. (Nelson Essentials)'),
    (v_topic_id, '158: A newborn presents with "snuffles" (copious rhinorrhea) and a maculopapular rash on the palms and soles. Diagnosis?', '["Congenital Rubella", "Congenital Syphilis", "Congenital CMV", "Neonatal Herpes"]', 1, 'Snuffles and the rash on palms/soles are classic for syphilis. (Nelson Essentials)'),
    (v_topic_id, '159: What is the triad of "Congenital Rubella"?', '["Cataracts, Sensorineural hearing loss, PDA", "Hydrocephalus, Intracranial calcifications, Chorioretinitis", "Microcephaly, Seizures, Rash", "Heart block, Rash, Anemia"]', 0, 'Cataracts, Deafness, and Heart defects (often PDA or peripheral PS) are the classic triad. (Nelson Essentials)'),
    (v_topic_id, '160: What is the triad of "Congenital Toxoplasmosis"?', '["Cataracts, Deafness, Heart defects", "Hydrocephalus, Chorioretinitis, Intracranial calcifications", "Snuffles, Rash, Saddle nose", "Hepatomegaly, Microcephaly, Jaundice"]', 1, 'Toxoplasmosis triad: Chorioretinitis, Hydrocephalus, and Intracranial calcifications. (Nelson Essentials)'),
    (v_topic_id, '161: Which congenital infection is most commonly associated with "periventricular" calcifications?', '["Toxoplasmosis", "CMV", "Syphilis", "Rubella"]', 1, 'CMV calcifications are periventricular, whereas Toxoplasmosis calcifications are diffuse throughout the parenchyma. (Nelson Essentials)'),
    (v_topic_id, '162: A child presents with a "webbed neck" and "coarctation of the aorta." Diagnosis?', '["Down Syndrome", "Turner Syndrome", "DiGeorge Syndrome", "Williams Syndrome"]', 1, 'Turner syndrome (45,X) is associated with webbed neck, short stature, and left-sided heart defects. (Nelson Essentials)'),
    (v_topic_id, '163: A neonate with Down Syndrome has no passage of meconium and a "double bubble" sign on X-ray. Diagnosis?', '["Hirschsprung disease", "Duodenal Atresia", "Pyloric stenosis", "Meconium ileus"]', 1, 'Duodenal atresia is highly associated with Trisomy 21. (Nelson Essentials)'),
    (v_topic_id, '164: A child with DiGeorge Syndrome is at high risk for which of the following in the neonatal period?', '["Hypercalcemia", "Hypocalcemia (seizures)", "Hypoglycemia", "Hypernatremia"]', 1, 'DiGeorge involves parathyroid hypoplasia/aplasia, leading to low calcium. (Nelson Essentials)'),
    (v_topic_id, '165: A 2-year-old child presents with "unilateral" foul-smelling, purulent nasal discharge. Diagnosis?', '["Sinusitis", "Nasal Foreign Body", "Choanal atresia", "Epistaxis"]', 1, 'Unilateral, foul-smelling discharge in a toddler is a nasal foreign body until proven otherwise. (Blueprints Pediatrics)'),
    (v_topic_id, '166: A child presents with "painless" swelling of the face and hands after an insect bite. There is no respiratory distress. What is this?', '["Anaphylaxis", "Angioedema", "Cellulitis", "Urticaria"]', 1, 'Localized angioedema without systemic symptoms is usually manageable with antihistamines. (Nelson Essentials)'),
    (v_topic_id, '167: What is the most common cause of "upper airway obstruction" in a child during sleep?', '["Croup", "Tonsillar and Adenoid hypertrophy", "Laryngomalacia", "Obesity"]', 1, 'Adenotonsillar hypertrophy is the leading cause of Obstructive Sleep Apnea (OSA) in children. (Nelson Essentials)'),
    (v_topic_id, '168: A child is found in a garage with a "charcoal grill" running. He has a headache and is sleepy. What is the definitive treatment?', '["Naloxone", "100% Oxygen", "Albuterol", "Activated charcoal"]', 1, '100% oxygen reduces the half-life of carboxyhemoglobin. (Nelson Essentials)'),
    (v_topic_id, '169: A 16-year-old boy presents with "sudden" right-sided chest pain and shortness of breath. He is tall and thin. Diagnosis?', '["Pneumonia", "Spontaneous Pneumothorax", "Pulmonary Embolism", "Asthma"]', 1, 'Primary spontaneous pneumothorax is common in tall, thin adolescent males. (Nelson Essentials)'),
    (v_topic_id, '170: A child presents with "strawberry tongue" and a "sandpaper" rash. Diagnosis?', '["Kawasaki Disease", "Scarlet Fever", "Toxic Shock Syndrome", "Measles"]', 1, 'Scarlet fever is caused by erythrogenic toxin from Group A Strep. (Nelson Essentials)'),
    (v_topic_id, '171: What is the most common cause of "primary" amenorrhea in a girl with a webbed neck and short stature?', '["Polycystic Ovarian Syndrome", "Turner Syndrome", "Pregnancy", "Anorexia"]', 1, 'Turner syndrome is a common cause of ovarian dysgenesis (streak ovaries). (Nelson Essentials)'),
    (v_topic_id, '172: A neonate presents with a "scaphoid abdomen" and loops of bowel in the chest. What should be AVOIDED during resuscitation?', '["Intubation", "Bag-mask ventilation", "Oxygen", "IV fluids"]', 1, 'Bag-mask ventilation forces air into the stomach/intestines in the chest, further compressing the lungs. (PALS Guidelines)'),
    (v_topic_id, '173: A child presents with "painless" scrotal swelling that transilluminates. Diagnosis?', '["Testicular torsion", "Hydrocele", "Inguinal hernia", "Varicocele"]', 1, 'Hydrocele is a collection of fluid in the tunica vaginalis. (Nelson Essentials)'),
    (v_topic_id, '174: A 15-year-old girl presents with "cyclic" abdominal pain but has never had a period. On exam, there is a bulging blue-tinged membrane at the vaginal opening. Diagnosis?', '["Pregnancy", "Imperforate Hymen", "Turner syndrome", "Endometriosis"]', 1, 'Hematocolpos (blood in the vagina) builds up behind the imperforate hymen. (Case Files Pediatrics)'),
    (v_topic_id, '175: What is the classic finding on an X-ray of a child with "necrotizing enterocolitis" (NEC)?', '["Double bubble", "Pneumatosis intestinalis (air in bowel wall)", "Thumbprinting", "Rigler sign"]', 1, 'Pneumatosis intestinalis is the hallmark of NEC. (Nelson Essentials)'),
    (v_topic_id, '176: A child presents with a "barky" cough that improves when exposed to cold night air. Diagnosis?', '["Epiglottitis", "Croup", "Asthma", "Pertussis"]', 1, 'Cold air or steam often helps relieve the subglottic edema in croup. (Blueprints Pediatrics)'),
    (v_topic_id, '177: What is the most common cause of "neonatal" sepsis?', '["Group B Streptococcus", "E. coli", "Listeria", "Staphylococcus aureus"]', 0, 'GBS is the #1 cause of early-onset neonatal sepsis. (Nelson Essentials)'),
    (v_topic_id, '178: A child presents with "sudden" profound weakness after a viral illness. He has lost his deep tendon reflexes. Diagnosis?', '["Polio", "Guillain-Barre Syndrome", "Myasthenia Gravis", "Botulism"]', 1, 'GBS is an acute inflammatory demyelinating polyneuropathy. (Nelson Essentials)'),
    (v_topic_id, '179: A 12-year-old child presents with a heart rate of 280 bpm and no P waves. He is stable. What is the initial treatment?', '["Synchronized cardioversion", "Adenosine 0.1 mg/kg IV", "Vagal maneuvers (e.g., ice to face)", "Amiodarone"]', 2, 'Vagal maneuvers should be attempted first in stable patients with SVT. (PALS Guidelines)'),
    (v_topic_id, '180: What is the mechanism of "Adenosine" in treating SVT?', '["Blocks sodium channels", "Slows conduction through the AV node", "Blocks calcium channels", "Increases sympathetic tone"]', 1, 'Adenosine temporarily blocks AV node conduction, which can break the re-entry circuit. (Nelson Essentials)'),
    (v_topic_id, '181: A child presents with a "harsh holosystolic" murmur at the left lower sternal border. Diagnosis?', '["ASD", "VSD", "PDA", "Tetralogy of Fallot"]', 1, 'VSD is the most common congenital heart defect. (Nelson Essentials)'),
    (v_topic_id, '182: A child presents with "widely split and fixed S2." Diagnosis?', '["VSD", "ASD", "PDA", "Pulmonary stenosis"]', 1, 'The split S2 in ASD is fixed because it does not vary with respiration. (Nelson Essentials)'),
    (v_topic_id, '183: A child presents with "muffled heart sounds" and "hypotension" after a chest injury. Diagnosis?', '["Pneumothorax", "Cardiac Tamponade", "Hemothorax", "Myocardial contusion"]', 1, 'Tamponade is a classic cause of obstructive shock in trauma. (PALS Guidelines)'),
    (v_topic_id, '184: What is the classic finding on an EKG of a child with "Wolff-Parkinson-White" (WPW) syndrome?', '["Long PR interval", "Short PR interval and Delta wave", "ST-segment elevation", "Inverted T waves"]', 1, 'WPW involves an accessory pathway that bypasses the AV node. (Nelson Essentials)'),
    (v_topic_id, '185: A child presents with "high fever" and a "toxic" appearance. He has a "thumbprint" sign on X-ray. What is the most likely causative organism?', '["Parainfluenza", "Haemophilus influenzae type b", "S. pneumoniae", "RSV"]', 1, 'Hib was the primary cause of epiglottitis before the vaccine. (Nelson Essentials)'),
    (v_topic_id, '186: A child presents with "recurrent" infections, "thrombocytopenia" (small platelets), and "eczema." Diagnosis?', '["DiGeorge Syndrome", "Wiskott-Aldrich Syndrome", "SCID", "Bruton agammaglobulinemia"]', 1, 'Wiskott-Aldrich is an X-linked recessive disorder (WATER mnemonic: Wiskott, Aldrich, Thrombocytopenia, Eczema, Recurrent infections). (Nelson Essentials)'),
    (v_topic_id, '187: A child presents with "absent" thymic shadow, "recurrent" viral/fungal infections, and failure to thrive. Diagnosis?', '["SCID (Severe Combined Immunodeficiency)", "Bruton", "Common Variable Immunodeficiency", "Chronic Granulomatous Disease"]', 0, 'SCID is a "bubble boy" disease with both B and T cell defects. (Nelson Essentials)'),
    (v_topic_id, '188: A child presents with "recurrent" abscesses and infections with "catalase-positive" organisms (e.g., S. aureus, Aspergillus). Diagnosis?', '["SCID", "Chronic Granulomatous Disease (CGD)", "Bruton", "Chediak-Higashi"]', 1, 'CGD is a defect in the NADPH oxidase enzyme (oxidative burst). (Nelson Essentials)'),
    (v_topic_id, '189: A child presents with "silver" hair and "giant granules" in neutrophils. Diagnosis?', '["CGD", "Chediak-Higashi Syndrome", "Job Syndrome", "Wiskott-Aldrich"]', 1, 'Chediak-Higashi involves a defect in lysosomal trafficking. (Nelson Essentials)'),
    (v_topic_id, '190: What is the most common "inherited" cause of intellectual disability?', '["Down Syndrome", "Fragile X Syndrome", "Prader-Willi", "Fetal Alcohol Syndrome"]', 1, 'Down syndrome is the most common genetic cause, but Fragile X is the most common *inherited* cause. (Nelson Essentials)'),
    (v_topic_id, '191: A child presents with a "long face," "large ears," and "macro-orchidism" (large testes). Diagnosis?', '["Klinefelter Syndrome", "Fragile X Syndrome", "Prader-Willi", "Noonan Syndrome"]', 1, 'Fragile X is caused by a CGG triplet repeat expansion in the FMR1 gene. (Nelson Essentials)'),
    (v_topic_id, '192: A child presents with "obesity," "small hands/feet," and "hypogonadism." Diagnosis?', '["Turner Syndrome", "Prader-Willi Syndrome", "Down Syndrome", "Fragile X"]', 1, 'Prader-Willi is a microdeletion on the paternal chromosome 15. (Nelson Essentials)'),
    (v_topic_id, '193: A child presents with "short stature," "pectus excavatum," and "pulmonic stenosis." He has a normal karyotype. Diagnosis?', '["Turner Syndrome", "Noonan Syndrome", "Marfan", "DiGeorge"]', 1, 'Noonan syndrome is sometimes called the "male Turner syndrome." (Nelson Essentials)'),
    (v_topic_id, '194: What is the most common cause of "hypercyanotic spells" (Tet spells) in children with Tetralogy of Fallot?', '["Increased systemic vascular resistance", "Decreased systemic vascular resistance (e.g., during exercise or crying)", "Increased pulmonary blood flow", "Decreased heart rate"]', 1, 'A drop in SVR increases the right-to-left shunt across the VSD. (Nelson Essentials)'),
    (v_topic_id, '195: A child presents with "hematuria" and a "palpable" abdominal mass. The most likely diagnosis is Wilms tumor. What is the most common site of metastasis?', '["Brain", "Bone", "Lungs", "Liver"]', 2, 'Wilms tumor classically metastasizes to the lungs. (Nelson Essentials)'),
    (v_topic_id, '196: A child presents with "weight loss," "night sweats," and "painless" cervical lymphadenopathy. Reed-Sternberg cells are seen on biopsy. Diagnosis?', '["Non-Hodgkin Lymphoma", "Hodgkin Lymphoma", "Leukemia", "Cat scratch disease"]', 1, 'Reed-Sternberg cells (owl eyes) are the hallmark of Hodgkin lymphoma. (Nelson Essentials)'),
    (v_topic_id, '197: A child presents with "acute" onset of "petechiae" and "bruising" after a viral illness. The WBC and Hb are normal, but platelets are 5,000. Diagnosis?', '["Leukemia", "ITP (Immune Thrombocytopenic Purpura)", "HUS", "DIC"]', 1, 'ITP in children is usually acute and self-limiting following a viral infection. (Nelson Essentials)'),
    (v_topic_id, '198: What is the management of a child with ITP and "mild" bleeding (petechiae only)?', '["Platelet transfusion", "IVIG", "Observation", "Steroids"]', 2, 'Observation is often sufficient for ITP if there is no significant mucosal bleeding. (Nelson Essentials)'),
    (v_topic_id, '199: A child presents with "bleeding" into the joints (hemarthrosis) and a prolonged PTT. PT is normal. Diagnosis?', '["Hemophilia A or B", "von Willebrand Disease", "ITP", "Vitamin K deficiency"]', 0, 'Hemophilias are X-linked recessive disorders of the intrinsic pathway. (Nelson Essentials)'),
    (v_topic_id, '200: What is the most common "inherited" bleeding disorder?', '["Hemophilia A", "von Willebrand Disease", "Factor V Leiden", "Protein C deficiency"]', 1, 'vWD affects both platelet adhesion and factor VIII stability. (Nelson Essentials)'),
    (v_topic_id, '201: A child presents with "nosebleeds" and a "prolonged" bleeding time. PT and PTT are normal. Diagnosis?', '["Hemophilia", "von Willebrand Disease (mild)", "ITP", "Aspirin ingestion"]', 1, 'vWD often presents with mucosal bleeding (epistaxis, menorrhagia). (Nelson Essentials)'),
    (v_topic_id, '202: A child presents with "bone pain," "fever," and a "high" WBC with "blasts" on the peripheral smear. Diagnosis?', '["ALL (Acute Lymphoblastic Leukemia)", "AML", "CML", "Lymphoma"]', 0, 'ALL is the most common malignancy of childhood. (Nelson Essentials)'),
    (v_topic_id, '203: A child presents with "fever," "bone pain," and "pancytopenia." What is the next diagnostic step?', '["Lymph node biopsy", "Bone marrow aspiration and biopsy", "CT scan", "Lumbar puncture"]', 1, 'Bone marrow biopsy is definitive for diagnosing leukemia. (Nelson Essentials)'),
    (v_topic_id, '204: A child presents with "abdominal pain," "vomiting," and "headache." He is noted to have a "lead line" on his gums and "basophilic stippling" on a blood smear. Diagnosis?', '["Iron poisoning", "Lead poisoning", "Mercury poisoning", "Arsenic poisoning"]', 1, 'Lead poisoning can cause encephalopathy and GI distress. (Nelson Essentials)'),
    (v_topic_id, '205: A child presents with "hyperphagia," "hypotonia," and "cryptorchidism." Diagnosis?', '["Prader-Willi Syndrome", "Down Syndrome", "Turner", "Klinefelter"]', 0, 'Prader-Willi involves a lack of expression of paternal genes on chromosome 15. (Nelson Essentials)'),
    (v_topic_id, '206: A child presents with "seizures" and "hypocalcemia." An X-ray of the heart shows "truncus arteriosus." Diagnosis?', '["DiGeorge Syndrome", "Down syndrome", "Williams", "Noonan"]', 0, 'DiGeorge is associated with conotruncal heart defects. (Nelson Essentials)'),
    (v_topic_id, '207: A child presents with "jaundice" and "splenomegaly." A peripheral smear shows "spherocytes" and the osmotic fragility test is positive. Diagnosis?', '["Sickle cell", "Hereditary Spherocytosis", "G6PD deficiency", "Thalassemia"]', 1, 'Spherocytosis is a defect in RBC membrane proteins (e.g., spectrin). (Nelson Essentials)'),
    (v_topic_id, '208: A child presents with "acute hemolysis" after eating "fava beans." Diagnosis?', '["Sickle cell", "G6PD deficiency", "Hereditary Spherocytosis", "Autoimmune hemolytic anemia"]', 1, 'G6PD deficiency is an X-linked disorder where cells cannot handle oxidative stress. (Nelson Essentials)'),
    (v_topic_id, '209: A child presents with "microcytic anemia" and a "target cells" on a smear. He is of Mediterranean descent. Diagnosis?', '["Iron deficiency", "Thalassemia", "Sickle cell", "Lead poisoning"]', 1, 'Beta-thalassemia is common in Mediterranean populations. (Nelson Essentials)'),
    (v_topic_id, '210: What is the treatment for "severe" thalassemia (Thalassemia Major)?', '["Iron supplements", "Chronic blood transfusions and chelation therapy", "Splenectomy", "Vitamin B12"]', 1, 'Chronic transfusion leads to iron overload, requiring chelation (e.g., Deferasirox). (Nelson Essentials)'),
    (v_topic_id, '211: A child presents with "fever" and "diffuse erythroderma" (like a sunburn). On day 3, the skin begins to peel in large sheets. The Nikolsky sign is positive. Diagnosis?', '["Bullous impetigo", "Staphylococcal Scalded Skin Syndrome (SSSS)", "Kawasaki Disease", "SJS"]', 1, 'SSSS is caused by exfoliative toxins from S. aureus. (Nelson Essentials)'),
    (v_topic_id, '212: What is the primary difference between SSSS and Stevens-Johnson Syndrome (SJS)?', '["SSSS involves the mucosa; SJS does not", "SJS involves the mucosa; SSSS does not", "SSSS has a negative Nikolsky sign", "There is no difference"]', 1, 'SJS/TEN involves significant mucosal involvement (mouth, eyes, genitals), which is typically absent in SSSS. (Nelson Essentials)'),
    (v_topic_id, '213: A child presents with a high fever and a "sandpaper" rash that spares the palms and soles. He has a "strawberry tongue." Diagnosis?', '["Scarlet Fever", "Measles", "Roseola", "Kawasaki"]', 0, 'Scarlet fever rash (scarlatina) is classic for Group A Strep. (Nelson Essentials)'),
    (v_topic_id, '214: A child presents with a fever, cough, coryza, and conjunctivitis. Two days later, a maculopapular rash starts on the head and moves down. Diagnosis?', '["Rubella", "Measles (Rubeola)", "Roseola", "Varicella"]', 1, 'Measles is characterized by the "3 Cs" and a cephalocaudal rash. (Nelson Essentials)'),
    (v_topic_id, '215: What are the small "white spots" on the buccal mucosa seen in measles called?', '["Forchheimer spots", "Koplik spots", "Janeway lesions", "Osler nodes"]', 1, 'Koplik spots are pathognomonic for measles. (Nelson Essentials)'),
    (v_topic_id, '216: A child presents with a "slapped-cheek" rash. Diagnosis?', '["Measles", "Erythema Infectiosum (Fifth Disease)", "Roseola", "Scarlet Fever"]', 1, 'Fifth disease is caused by Parvovirus B19. (Nelson Essentials)'),
    (v_topic_id, '217: A child presents with a high fever for 3 days. When the fever breaks, a rosy rash appears on the trunk. Diagnosis?', '["Roseola Infantum (Sixth Disease)", "Measles", "Rubella", "Varicella"]', 0, 'Roseola (HHV-6) is famous for "rash after fever." (Nelson Essentials)'),
    (v_topic_id, '218: A child presents with "crops" of vesicles in various stages of healing (papule, vesicle, crust). Diagnosis?', '["Hand-Foot-Mouth", "Varicella (Chickenpox)", "Smallpox", "Impetigo"]', 1, 'Varicella lesions appear in successive crops. (Nelson Essentials)'),
    (v_topic_id, '219: A child presents with "fever" and a "petechial" rash that started on the ankles/wrists and moved centrally. He was recently hiking in the woods. Diagnosis?', '["Meningococcemia", "Rocky Mountain Spotted Fever (RMSF)", "Lyme Disease", "ITP"]', 1, 'RMSF is caused by Rickettsia rickettsii and starts on the extremities. (Nelson Essentials)'),
    (v_topic_id, '220: What is the first-line treatment for Rocky Mountain Spotted Fever in children of ALL ages?', '["Amoxicillin", "Doxycycline", "Ceftriaxone", "Azithromycin"]', 1, 'Doxycycline is used for RMSF regardless of age to prevent fatal outcomes. (Nelson Essentials)'),
    (v_topic_id, '221: A child presents with a "target-like" (bull''s-eye) rash after a tick bite. Diagnosis?', '["RMSF", "Lyme Disease (Erythema Migrans)", "Erythema Multiforme", "Nummular eczema"]', 1, 'Lyme disease is caused by Borrelia burgdorferi. (Nelson Essentials)'),
    (v_topic_id, '222: What is the first-line treatment for early localized Lyme disease in a 10-year-old child?', '["Amoxicillin", "Doxycycline", "Ceftriaxone", "Penicillin"]', 1, 'Doxycycline is the preferred treatment for Lyme disease in children > 8 years. Amoxicillin is used for younger children. (Nelson Essentials)'),
    (v_topic_id, '223: A child presents with "hives" and "lip swelling" after eating a peanut. He is wheezing. BP is 80/40. What is the dose of Epinephrine?', '["0.3 mg IM", "0.01 mg/kg IM of 1:1,000", "0.1 mg IV", "0.5 mg IM"]', 1, 'IM Epinephrine at 0.01 mg/kg is the standard for anaphylaxis. (PALS Guidelines)'),
    (v_topic_id, '224: A 2-year-old child presents with a "second-degree" burn over 20% of his body. What is the best chart for calculating TBSA (Total Body Surface Area) in a child?', '["Rule of 9s", "Lund-Browder Chart", "Rule of 10s", "Glasgow Coma Scale"]', 1, 'The Lund-Browder chart accounts for the larger head-to-body ratio in children. (Nelson Essentials)'),
    (v_topic_id, '225: What is the "Parkland Formula" for fluid resuscitation in burns?', '["2 mL x kg x %TBSA", "4 mL x kg x %TBSA", "10 mL x kg x %TBSA", "20 mL/kg bolus"]', 1, '4 mL/kg/%TBSA of crystalloid is the standard formula for the first 24 hours. (Nelson Essentials)'),
    (v_topic_id, '226: When calculating burn resuscitation fluids, when should the first half of the total volume be administered?', '["Over 24 hours", "Over the first 8 hours", "Over the first 4 hours", "Immediately"]', 1, 'Half of the calculated 24-hour volume is given in the first 8 hours from the time of injury. (Nelson Essentials)'),
    (v_topic_id, '227: A child presents with "circumferential" burns to the arm and a weak pulse. What procedure may be necessary?', '["Amputation", "Escharotomy", "Fasciotomy", "Skin graft"]', 1, 'Escharotomy relieves the pressure from tight, burnt skin that can compromise perfusion. (Nelson Essentials)'),
    (v_topic_id, '228: A child presents with "black, charred" skin that is painless. What degree of burn is this?', '["First degree", "Second degree (Partial thickness)", "Third degree (Full thickness)", "Fourth degree"]', 2, 'Third-degree burns involve all layers of the skin and damage sensory nerves. (Nelson Essentials)'),
    (v_topic_id, '229: What is the most common cause of "early" death in a pediatric burn patient?', '["Sepsis", "Airway injury and smoke inhalation", "Hypovolemic shock", "Renal failure"]', 1, 'Inhalation injury is a major predictor of mortality. (Nelson Essentials)'),
    (v_topic_id, '230: A child presents after a "near-drowning." He is awake but has significant wheezing. What is the most common "late" pulmonary complication?', '["Pneumonia", "ARDS (Acute Respiratory Distress Syndrome)", "Pulmonary edema", "Pneumothorax"]', 1, 'ARDS can develop hours after the initial insult due to surfactant washout and inflammation. (PALS Guidelines)'),
    (v_topic_id, '231: A child presents with "ice-cold" hands and white, waxy skin after playing in the snow. Diagnosis?', '["Frostnip", "Frostbite", "Raynaud''s", "Hypothermia"]', 1, 'Frostbite involves tissue freezing and can lead to necrosis. (Nelson Essentials)'),
    (v_topic_id, '232: What is the proper way to rewarm a frostbitten limb?', '["Rub the limb vigorously", "Rapid rewarming in warm water (37-40 C)", "Hold over a fire", "Wait for it to thaw at room temperature"]', 1, 'Rapid rewarming in a warm water bath is the standard. Avoid rubbing as it damages frozen tissues. (Nelson Essentials)'),
    (v_topic_id, '233: A child presents with a "bull''s-eye" lesion on the thigh that becomes necrotic and develops a black eschar. He was playing in a woodpile. What bit him?', '["Black Widow spider", "Brown Recluse spider", "Tick", "Bee"]', 1, 'Brown Recluse (Loxosceles reclusa) venom causes localized skin necrosis. (Nelson Essentials)'),
    (v_topic_id, '234: A child presents with severe "abdominal muscle spasms" and pain after a spider bite. What bit him?', '["Brown Recluse", "Black Widow", "Tarantula", "Scorpion"]', 1, 'Black Widow (Latrodectus mactans) venom is neurotoxic and causes muscle spasms. (Nelson Essentials)'),
    (v_topic_id, '235: A child presents with "hypotension" and "urticaria" after a bee sting. What is the mechanism?', '["Type I Hypersensitivity (IgE-mediated)", "Type II Hypersensitivity", "Type III Hypersensitivity", "Type IV Hypersensitivity"]', 0, 'Anaphylaxis is a classic Type I hypersensitivity reaction. (Nelson Essentials)'),
    (v_topic_id, '236: A 2-year-old is brought to the ER with a "scald" burn on his buttocks and perineum. The edges are sharp and there are no splash marks. What do you suspect?', '["Accidental burn", "Child Abuse (Forced immersion)", "SSSS", "Bullous impetigo"]', 1, 'Sharply demarcated burns in a "glove" or "stocking" distribution or on the buttocks/perineum without splashes are highly suspicious for abuse. (Nelson Essentials)'),
    (v_topic_id, '237: A 6-month-old presents with "retinal hemorrhages" and a "subdural hematoma." He was reportedly "shaken" to wake him up. Diagnosis?', '["Accidental fall", "Abusive Head Trauma (Shaken Baby Syndrome)", "Hydrocephalus", "Meningitis"]', 1, 'The triad of subdural hemorrhage, retinal hemorrhage, and encephalopathy is classic for AHT. (Nelson Essentials)'),
    (v_topic_id, '238: What is the most common cause of "traumatic" death in children?', '["Burns", "Drowning", "Head Trauma", "Abdominal injuries"]', 2, 'Head injury is the leading cause of mortality in pediatric trauma. (Nelson Essentials)'),
    (v_topic_id, '239: A child is hit by a car and has a "brief loss of consciousness" followed by a "lucid interval" and then rapid deterioration. Diagnosis?', '["Subdural hematoma", "Epidural hematoma", "Concussion", "Subarachnoid hemorrhage"]', 1, 'Epidural hematoma is typically due to a middle meningeal artery tear. (Nelson Essentials)'),
    (v_topic_id, '240: What is the "shape" of an epidural hematoma on CT?', '["Crescent-shaped", "Lens-shaped (biconvex)", "Irregular", "Star-shaped"]', 1, 'Epidural hematomas are biconvex because they are limited by suture lines. (Nelson Essentials)'),
    (v_topic_id, '241: What is the "shape" of a subdural hematoma on CT?', '["Crescent-shaped", "Lens-shaped", "Circular", "Triangle"]', 0, 'Subdural hematomas cross suture lines but are limited by dural reflections. (Nelson Essentials)'),
    (v_topic_id, '242: A child presents with "chest pain" and a "friction rub" after a viral infection. He feels better when leaning forward. Diagnosis?', '["Pneumonia", "Pericarditis", "Myocarditis", "Asthma"]', 1, 'Pericarditis typically causes pleuritic chest pain that improves with leaning forward. (Nelson Essentials)'),
    (v_topic_id, '243: A child presents with "congestive heart failure" (tachycardia, hepatomegaly, gallop) 2 weeks after a flu-like illness. Diagnosis?', '["Endocarditis", "Myocarditis", "Pericarditis", "Rheumatic Fever"]', 1, 'Viral myocarditis (often Coxsackie or Adenovirus) can lead to dilated cardiomyopathy and heart failure. (Nelson Essentials)'),
    (v_topic_id, '244: What is the "Jones Criteria" used for?', '["Diagnosing Acute Rheumatic Fever", "Diagnosing Kawasaki Disease", "Diagnosing Sepsis", "Diagnosing SLE"]', 0, 'Jones Criteria (JONES: Joint pain, O-heart/carditis, Nodules, Erythema marginatum, Sydenham chorea). (Nelson Essentials)'),
    (v_topic_id, '245: A child presents with "involuntary, jerky movements" of the hands and face (chorea) after a sore throat. Diagnosis?', '["Huntington Chorea", "Sydenham Chorea", "Tics", "Seizure"]', 1, 'Sydenham chorea is a major Jones criterion for Rheumatic Fever. (Nelson Essentials)'),
    (v_topic_id, '246: What is the most common "valve" affected in Rheumatic Heart Disease?', '["Aortic valve", "Mitral valve", "Tricuspid valve", "Pulmonary valve"]', 1, 'Mitral regurgitation is the most common early finding in rheumatic carditis. (Nelson Essentials)'),
    (v_topic_id, '247: A child presents with a "harsh systolic" murmur and "fever" after a dental procedure. He has "splinter hemorrhages" in his nails. Diagnosis?', '["Rheumatic Fever", "Infective Endocarditis", "Kawasaki", "Myocarditis"]', 1, 'Endocarditis should be suspected in children with underlying heart disease and persistent fever. (Nelson Essentials)'),
    (v_topic_id, '248: A child presents with "edema," "hypoalbuminemia," and "massive proteinuria" (> 3.5g/day). Diagnosis?', '["Nephritic Syndrome", "Nephrotic Syndrome", "Heart failure", "Liver failure"]', 1, 'Nephrotic syndrome is characterized by heavy protein loss in the urine. (Nelson Essentials)'),
    (v_topic_id, '249: What is the most common cause of "nephrotic syndrome" in children?', '["Membranous Nephropathy", "Minimal Change Disease", "FSGS", "Diabetes"]', 1, 'Minimal Change Disease is highly responsive to steroids. (Nelson Essentials)'),
    (v_topic_id, '250: What is the first-line treatment for Minimal Change Disease?', '["Antibiotics", "Corticosteroids (Prednisone)", "Diuretics", "ACE inhibitors"]', 1, 'The majority of children with MCD respond well to a course of steroids. (Nelson Essentials)'),
    (v_topic_id, '251: A child presents with "dark, tea-colored urine" and hypertension. Diagnosis?', '["Nephrotic Syndrome", "Nephritic Syndrome", "UTI", "Kidney stone"]', 1, 'Nephritic syndrome involves hematuria (red cell casts) and hypertension. (Nelson Essentials)'),
    (v_topic_id, '252: A 2-year-old child presents with a "midline" abdominal wall defect where the bladder is exposed. Diagnosis?', '["Omphalocele", "Bladder Exstrophy", "Gastroschisis", "Urachal cyst"]', 1, 'Bladder exstrophy is a rare congenital anomaly where the bladder is open to the abdominal wall. (Nelson Essentials)'),
    (v_topic_id, '253: A child presents with "hypokalemia" and "muscle weakness." He has been vomiting for 2 days. What is the most common acid-base disorder?', '["Metabolic Acidosis", "Metabolic Alkalosis", "Respiratory Acidosis", "Respiratory Alkalosis"]', 1, 'Vomiting causes loss of HCl, leading to hypochloremic metabolic alkalosis. (Nelson Essentials)'),
    (v_topic_id, '254: What is the most common cause of "metabolic acidosis" in a pediatric patient with diarrhea?', '["Loss of gastric acid", "Loss of bicarbonate in stool", "Renal failure", "Lactic acidosis from shock"]', 1, 'Diarrhea involves loss of bicarbonate, causing a normal anion gap metabolic acidosis. (Nelson Essentials)'),
    (v_topic_id, '255: A child presents with a "high anion gap" metabolic acidosis after ingesting "aspirin." What is the treatment for severe salicylate poisoning?', '["Naloxone", "Alkalinization of urine (Sodium Bicarbonate) and Hemodialysis", "Activated charcoal only", "Vitamin K"]', 1, 'Bicarbonate traps the salicylate in the urine for excretion. (Nelson Essentials)'),
    (v_topic_id, '256: A child presents with "seizures" and "hyponatremia" after being given a large amount of free water. What is the danger of correcting sodium too rapidly?', '["Cerebral edema", "Central Pontine Myelinolysis (Osmotic Demyelination Syndrome)", "Heart failure", "Renal failure"]', 1, 'Rapid correction of hyponatremia can damage the brainstem. (Nelson Essentials)'),
    (v_topic_id, '257: A child presents with "peaked T waves" on ECG and a K+ of 7.0. What is the first-line medication to stabilize the cardiac membrane?', '["Insulin", "Albuterol", "Calcium Gluconate", "Furosemide"]', 2, 'Calcium gluconate does not lower K+ but protects the heart from arrhythmias. (PALS Guidelines)'),
    (v_topic_id, '258: A child presents with "abdominal pain," "arthritis," and "palpable purpura." He is found to have "intussusception." What is the most common site of intussusception in HSP?', '["Ileo-colic", "Ileo-ileal", "Colo-colic", "Gastro-duodenal"]', 1, 'Unlike typical idiopathic intussusception (ileo-colic), HSP intussusception is often small-bowel to small-bowel. (Nelson Essentials)'),
    (v_topic_id, '259: A 6-month-old infant is noted to have a "clenched hand" with overlapping fingers and "rocker-bottom" feet. Diagnosis?', '["Trisomy 21", "Trisomy 18 (Edwards Syndrome)", "Trisomy 13 (Patau Syndrome)", "Turner Syndrome"]', 1, 'Edwards syndrome is characterized by severe developmental delay and these physical findings. (Nelson Essentials)'),
    (v_topic_id, '260: A neonate presents with "cleft lip/palate," "polydactyly," and "microphthalmia." Diagnosis?', '["Trisomy 13 (Patau Syndrome)", "Trisomy 18", "Down Syndrome", "DiGeorge"]', 0, 'Patau syndrome involves midline jealous and extra digits. (Nelson Essentials)'),
    (v_topic_id, '261: What is the most common cause of "ambiguous genitalia" in a 46,XX infant?', '["Turner Syndrome", "Congenital Adrenal Hyperplasia (CAH)", "Androgen Insensitivity", "Klinefelter"]', 1, 'Excess androgens in CAH virilize the female fetus. (Nelson Essentials)'),
    (v_topic_id, '262: A child presents with a "musty" body odor and intellectual disability. Diagnosis?', '["PKU (Phenylketonuria)", "Maple Syrup Urine Disease", "Galactosemia", "Homocystinuria"]', 0, 'PKU is a defect in phenylalanine hydroxylase. (Nelson Essentials)'),
    (v_topic_id, '263: A child presents with "cataracts" and "jaundice" after starting breast milk. Diagnosis?', '["PKU", "Galactosemia", "Biliary atresia", "Gilbert syndrome"]', 1, 'Galactosemia is a medical emergency; the infant cannot metabolize galactose in milk. (Nelson Essentials)'),
    (v_topic_id, '264: A child presents with "urine that smells like burnt sugar." Diagnosis?', '["PKU", "Maple Syrup Urine Disease", "Cystinuria", "Tyrosinemia"]', 1, 'MSUD involves a defect in branched-chain amino acid metabolism. (Nelson Essentials)'),
    (v_topic_id, '265: What is the treatment for "classic" galactosemia?', '["Soy-based formula (Lactose-free)", "High-protein diet", "Low-fat diet", "Antibiotics"]', 0, 'Strict avoidance of lactose and galactose is life-saving. (Nelson Essentials)'),
    (v_topic_id, '266: A child presents with "recurrent" episodes of "hypoketotic hypoglycemia" during fasting. Diagnosis?', '["DKA", "MCAD Deficiency", "GSD Type I", "Insulinoma"]', 1, 'Medium-chain acyl-CoA dehydrogenase (MCAD) deficiency is a fatty acid oxidation disorder. (Nelson Essentials)'),
    (v_topic_id, '267: A child presents with "hyperammonemia" and "vomiting" after a high-protein meal. There is no acidosis. Diagnosis?', '["Urea Cycle Disorder (e.g., OTC deficiency)", "Organic acidemia", "Maple syrup urine disease", "Sepsis"]', 0, 'Urea cycle defects prevent the clearance of ammonia. (Nelson Essentials)'),
    (v_topic_id, '268: What is the most common "X-linked" urea cycle disorder?', '["Ornithine Transcarbamylase (OTC) deficiency", "Citrullinemia", "Argininosuccinic aciduria", "Carbamoyl phosphate synthetase I"]', 0, 'OTC deficiency is the most common urea cycle disorder. (Nelson Essentials)'),
    (v_topic_id, '269: A child presents with "intellectual disability," "lens dislocation (downward)," and a high risk of "thromboembolism." Diagnosis?', '["Marfan Syndrome", "Homocystinuria", "Ehlers-Danlos", "Cystic Fibrosis"]', 1, 'Homocystinuria mimics Marfan but includes intellectual disability and downward lens subluxation. (Nelson Essentials)'),
    (v_topic_id, '270: A child presents with "tall stature," "long fingers (arachnodactyly)," and "upward lens dislocation." Diagnosis?', '["Homocystinuria", "Marfan Syndrome", "Noonan", "Achondroplasia"]', 1, 'Marfan is an autosomal dominant defect in the fibrillin-1 gene. (Nelson Essentials)'),
    (v_topic_id, '271: What is the most dangerous complication of Marfan Syndrome?', '["Scoliosis", "Aortic dissection/dilation", "Mitral valve prolapse", "Pneumothorax"]', 1, 'Progressive aortic root dilation is the leading cause of death in Marfan syndrome. (Nelson Essentials)'),
    (v_topic_id, '272: A child presents with "hyperflexible" skin and "hypermobile" joints. Diagnosis?', '["Marfan", "Ehlers-Danlos Syndrome", "Osteogenesis Imperfecta", "Rickets"]', 1, 'Ehlers-Danlos is a group of connective tissue disorders affecting collagen. (Nelson Essentials)'),
    (v_topic_id, '273: A child presents with "blue sclera" and multiple fractures from minor trauma. Diagnosis?', '["Child abuse", "Osteogenesis Imperfecta", "Rickets", "Hypophosphatasia"]', 1, 'OI is caused by defects in Type I collagen synthesis. (Nelson Essentials)'),
    (v_topic_id, '274: A 1-year-old child presents with "bowed legs" and "wrist widening." He is exclusively breastfed without vitamin D supplements. Diagnosis?', '["Scurvy", "Rickets", "Blount disease", "Physiologic bowing"]', 1, 'Nutritional rickets is caused by Vitamin D deficiency. (Nelson Essentials)'),
    (v_topic_id, '275: A child presents with "swollen, bleeding gums" and "corkscrew hairs." Diagnosis?', '["Scurvy (Vitamin C deficiency)", "Rickets", "Pellagra", "Beri-beri"]', 0, 'Scurvy involves defective collagen cross-linking. (Nelson Essentials)'),
    (v_topic_id, '276: A child presents with "night blindness" and "Bitot spots" on the conjunctiva. Diagnosis?', '["Vitamin A deficiency", "Vitamin D deficiency", "Vitamin E deficiency", "Zinc deficiency"]', 0, 'Vitamin A is essential for retinal function. (Nelson Essentials)'),
    (v_topic_id, '277: A child presents with "dermatitis," "diarrhea," and "dementia." Diagnosis?', '["Pellagra (Niacin deficiency)", "Scurvy", "Beri-beri", "Sepsis"]', 0, 'Pellagra (Vitamin B3 deficiency) presents with the "3 Ds." (Nelson Essentials)'),
    (v_topic_id, '278: A child presents with "heart failure" and "edema" (wet beri-beri). Diagnosis?', '["Thiamine (B1) deficiency", "Riboflavin (B2) deficiency", "Niacin deficiency", "Folic acid deficiency"]', 0, 'Thiamine deficiency can cause high-output heart failure. (Nelson Essentials)'),
    (v_topic_id, '279: A child presents with "hair loss," "rash around the mouth," and "diarrhea." Diagnosis?', '["Zinc deficiency (Acrodermatitis enteropathica)", "Iron deficiency", "Copper deficiency", "Selenium deficiency"]', 0, 'Zinc deficiency can be inherited or acquired. (Nelson Essentials)'),
    (v_topic_id, '280: A child presents with "hypochromic, microcytic anemia" and "pica" (eating ice or dirt). Diagnosis?', '["Lead poisoning", "Iron deficiency anemia", "Thalassemia", "Sideroblastic anemia"]', 1, 'Iron deficiency is the most common nutritional deficiency in children. (Nelson Essentials)'),
    (v_topic_id, '281: What is the most common cause of "upper airway obstruction" in an unconscious child?', '["Croup", "The tongue falling backward", "Epiglottitis", "Vomitus"]', 1, 'In the unconscious patient, loss of muscle tone allows the tongue to occlude the oropharynx. Head-tilt/chin-lift is the initial remedy. (PALS Guidelines)'),
    (v_topic_id, '282: A child presents with "unilateral" wheezing that does not respond to albuterol. What is the most likely diagnosis?', '["Asthma", "Foreign body aspiration", "Pneumonia", "Bronchiolitis"]', 1, 'Focal wheezing is a hallmark of foreign body aspiration. (Blueprints Pediatrics)'),
    (v_topic_id, '283: A child is found in a garage with a "charcoal" fire and has a headache. What is the danger of relying on standard pulse oximetry?', '["It measures CO2 instead of O2", "It cannot distinguish carboxyhemoglobin from oxyhemoglobin", "It is always too low", "It is always too high"]', 1, 'Standard pulse ox (SpO2) will be falsely normal/high in carbon monoxide poisoning. (Nelson Essentials)'),
    (v_topic_id, '284: A 15-year-old girl is found with an empty bottle of "amitriptyline." Her ECG shows a QRS duration of 140 ms. What is the immediate treatment?', '["Lidocaine", "Sodium Bicarbonate IV", "Amiodarone", "Magnesium"]', 1, 'Sodium bicarbonate is used to overcome the sodium channel blockade of TCAs. (Nelson Essentials)'),
    (v_topic_id, '285: A child presents with "abdominal pain," "vomiting," and "metabolic acidosis" after ingesting his mother''s prenatal vitamins. What do you suspect?', '["Acetaminophen poisoning", "Iron poisoning", "Vitamin A poisoning", "Lead poisoning"]', 1, 'Iron poisoning is common and can be fatal. Early symptoms are GI-related. (Nelson Essentials)'),
    (v_topic_id, '286: A child presents with "salivation," "lacrimation," "urination," and "defecation" (SLUDGE). What bit him or what did he ingest?', '["Black Widow spider", "Organophosphate insecticide", "Opioids", "Aspirin"]', 1, 'Cholinergic crisis from organophosphates. (Nelson Essentials)'),
    (v_topic_id, '287: A child is brought in after ingesting "antifreeze" (ethylene glycol). What is the major organ at risk for damage from oxalate crystals?', '["Liver", "Kidneys", "Brain", "Lungs"]', 1, 'Ethylene glycol causes acute tubular necrosis due to calcium oxalate crystal deposition. (BRS Pediatrics)'),
    (v_topic_id, '288: What is the specific "antidote" for ethylene glycol or methanol poisoning?', '["Fomepizole or Ethanol", "N-acetylcysteine", "Naloxone", "Flumazenil"]', 0, 'Fomepizole inhibits alcohol dehydrogenase, preventing the formation of toxic metabolites. (Nelson Essentials)'),
    (v_topic_id, '289: A child presents with "cyanosis" and a pulse oximetry reading of 85% that does not change with 100% oxygen. The blood is "chocolate" colored. Diagnosis?', '["Carbon monoxide poisoning", "Methemoglobinemia", "Cyanide poisoning", "Iron poisoning"]', 1, 'Oxidative stress (e.g., from benzocaine or nitrites) converts hemoglobin to methemoglobin (Fe3+). (Nelson Essentials)'),
    (v_topic_id, '290: A 2-year-old is brought to the ER after a "seizure." He has been "munching" on paint chips in an old house. Diagnosis?', '["Lead poisoning", "Iron poisoning", "Mercury poisoning", "Arsenic"]', 0, 'Lead encephalopathy can present with seizures and altered mental status. (Nelson Essentials)'),
    (v_topic_id, '291: A child presents with "ataxia," "slurred speech," and "nystagmus" after ingesting his mother''s "clonazepam." Diagnosis?', '["Opioid overdose", "Benzodiazepine overdose", "Alcohol poisoning", "TCA overdose"]', 1, 'Benzodiazepines cause CNS depression but typically minimal respiratory depression unless combined with other agents. (Nelson Essentials)'),
    (v_topic_id, '292: What is the "reversal agent" for benzodiazepine overdose (to be used with caution)?', '["Naloxone", "Flumazenil", "Atropine", "Physostigmine"]', 1, 'Flumazenil can precipitate seizures, especially in chronic users or co-ingestions. (Nelson Essentials)'),
    (v_topic_id, '293: A child presents with "bradycardia," "hypotension," and "hypoglycemia" after ingesting his father''s blood pressure medication. What medication class is this?', '["Calcium Channel Blockers", "Beta-blockers", "ACE inhibitors", "Diuretics"]', 1, 'Beta-blocker overdose classically causes bradycardia, hypotension, and hypoglycemia (by blocking gluconeogenesis). (Nelson Essentials)'),
    (v_topic_id, '294: A child presents with "bradycardia," "hypotension," and "hyperglycemia" after ingesting blood pressure medication. What medication class is this?', '["Beta-blockers", "Calcium Channel Blockers", "ACE inhibitors", "Digoxin"]', 1, 'CCB overdose (especially verapamil/diltiazem) causes hyperglycemia because insulin release is calcium-dependent. (Nelson Essentials)'),
    (v_topic_id, '295: What is a "rescue" treatment for severe beta-blocker or calcium channel blocker overdose?', '["Naloxone", "High-dose Insulin/Glucose and Glucagon", "Atropine", "Sodium Bicarbonate"]', 1, 'High-dose insulin (HDI) is a potent inotrope in these toxic states. (PALS Guidelines)'),
    (v_topic_id, '296: A child presents with "visual disturbances" (yellow-green halos) and "bradycardia." Diagnosis?', '["Digoxin toxicity", "Lead poisoning", "Methanol poisoning", "Aspirin"]', 0, 'Digoxin toxicity can also cause significant hyperkalemia. (Nelson Essentials)'),
    (v_topic_id, '297: A child presents with "lethargy," "vomiting," and a "liver that is shrinking" in size. He has a history of high fever and aspirin use for a viral illness. Diagnosis?', '["Hepatic Hemangioma", "Reye Syndrome", "Biliary atresia", "Hepatitis A"]', 1, 'Reye syndrome involves microvesicular steatosis and acute encephalopathy. (Nelson Essentials)'),
    (v_topic_id, '298: A 16-year-old girl with a history of "depression" presents with "vomiting" and "RUQ pain" 2 days after an intentional overdose. What organ is most likely failing?', '["Kidneys", "Liver", "Heart", "Lungs"]', 1, 'Acetaminophen (Tylenol) poisoning causes centrilobular hepatic necrosis. (Nelson Essentials)'),
    (v_topic_id, '299: A child presents with "bloody emesis." He has a history of "biliary atresia" and a Kasai procedure. What is the most likely cause?', '["Peptic ulcer", "Esophageal varices", "Mallory-Weiss tear", "Gastritis"]', 1, 'Portal hypertension from cirrhosis leads to the development of varices. (Nelson Essentials)'),
    (v_topic_id, '300: What is the primary medical treatment to "stop" active variceal bleeding in a child?', '["Propranolol", "Octreotide IV", "Aspirin", "Antibiotics"]', 1, 'Octreotide (somatostatin analog) causes splanchnic vasoconstriction. (Nelson Essentials)'),
    (v_topic_id, '301: A child presents with "acute abdominal pain" and an "elevated lipase" level. Diagnosis?', '["Appendicitis", "Pancreatitis", "Intussusception", "Cholecystitis"]', 1, 'Lipase is more sensitive and specific than amylase for pancreatitis in children. (Nelson Essentials)'),
    (v_topic_id, '302: What is the most common cause of "acute pancreatitis" in a pediatric patient?', '["Alcohol", "Gallstones", "Trauma (e.g., handlebar injury)", "Cystic Fibrosis"]', 2, 'Blunt abdominal trauma is a frequent cause of pancreatitis in children. (Nelson Essentials)'),
    (v_topic_id, '303: A child presents with "jaundice" and "acholic (white) stools" in the first 2 months of life. Diagnosis?', '["Physiologic jaundice", "Biliary Atresia", "Breast milk jaundice", "Gilbert syndrome"]', 1, 'Biliary atresia is a progressive fibro-obliterative disease of the extrahepatic biliary tree. (Nelson Essentials)'),
    (v_topic_id, '304: A child with cystic fibrosis presents with "sudden" abdominal pain and "failure to pass stool." Diagnosis?', '["Intussusception", "Distal Intestinal Obstruction Syndrome (DIOS)", "Volvulus", "Appendicitis"]', 1, 'DIOS (meconium ileus equivalent) involves thick stool obstructing the terminal ileum/cecum. (Nelson Essentials)'),
    (v_topic_id, '305: A 6-year-old child presents with "morning headaches" and "unsteady gait (ataxia)." What is the first priority?', '["Head CT/MRI", "Lumbar puncture", "EEG", "Physical therapy"]', 0, 'Morning headaches and ataxia suggest a posterior fossa brain tumor. (Nelson Essentials)'),
    (v_topic_id, '306: What is the most common "malignant" brain tumor in children?', '["Astrocytoma", "Medulloblastoma", "Ependymoma", "Craniopharyngioma"]', 1, 'Medulloblastoma typically arises in the cerebellum. (Nelson Essentials)'),
    (v_topic_id, '307: A child presents with "short stature," "bitemporal hemianopsia," and a CT showing a calcified mass. Diagnosis?', '["Medulloblastoma", "Craniopharyngioma", "Pituitary adenoma", "Optic glioma"]', 1, 'Craniopharyngioma is derived from Rathke''s pouch and can compress the optic chiasm. (Nelson Essentials)'),
    (v_topic_id, '308: A child presents with "precocious puberty," "cafe-au-lait spots," and "polyostotic fibrous dysplasia." Diagnosis?', '["Neurofibromatosis", "McCune-Albright Syndrome", "Tuberous Sclerosis", "Noonan"]', 1, 'McCune-Albright is due to a G-protein mutation. (Nelson Essentials)'),
    (v_topic_id, '309: A child presents with "> 6 cafe-au-lait spots," "axillary freckling," and "Lisch nodules." Diagnosis?', '["Neurofibromatosis Type 1", "Neurofibromatosis Type 2", "Tuberous Sclerosis", "Sturge-Weber"]', 0, 'NF1 is a common neurocutaneous syndrome. (Nelson Essentials)'),
    (v_topic_id, '310: A child presents with "bilateral acoustic neuromas." Diagnosis?', '["NF1", "Neurofibromatosis Type 2", "Tuberous Sclerosis", "Von Hippel-Lindau"]', 1, 'NF2 involves chromosome 22. (Nelson Essentials)'),
    (v_topic_id, '311: A child presents with "seizures," "intellectual disability," and "facial angiofibromas." Diagnosis?', '["Neurofibromatosis", "Tuberous Sclerosis Complex", "Sturge-Weber", "Ataxia-telangiectasia"]', 1, 'TSC also involves ash-leaf spots and cardiac rhabdomyomas. (Nelson Essentials)'),
    (v_topic_id, '312: A child presents with a "port-wine stain" in the V1/V2 distribution and seizures. Diagnosis?', '["Sturge-Weber Syndrome", "Neurofibromatosis", "Tuberous Sclerosis", "Lyme"]', 0, 'Sturge-Weber involves leptomeningeal angiomas. (Nelson Essentials)'),
    (v_topic_id, '313: A child presents with "recurrent sinopulmonary infections," "ataxia," and "telangiectasias." Diagnosis?', '["Ataxia-telangiectasia", "SCID", "Cystic Fibrosis", "Wiskott-Aldrich"]', 0, 'A-T involves a defect in ATM gene and DNA repair. (Nelson Essentials)'),
    (v_topic_id, '314: A child presents with "recurrent" infections and "low levels of all immunoglobulins." Diagnosis?', '["Selective IgA deficiency", "Common Variable Immunodeficiency (CVID)", "X-linked Agammaglobulinemia", "DiGeorge"]', 2, 'Bruton''s involves a lack of mature B cells. (Nelson Essentials)'),
    (v_topic_id, '315: What is the most common "primary" immunodeficiency?', '["SCID", "Selective IgA Deficiency", "Bruton''s", "CVID"]', 1, 'Most IgA deficient individuals are asymptomatic. (Nelson Essentials)'),
    (v_topic_id, '316: A child presents with "prolonged bleeding" after circumcision. Diagnosis?', '["ITP", "Hemophilia A", "vWD", "Vitamin K deficiency"]', 1, 'Hemophilia is a common cause of neonatal bleeding from procedures. (Nelson Essentials)'),
    (v_topic_id, '317: A child presents with "bone pain" that is "worse at night" and relieved by aspirin. Diagnosis?', '["Osteosarcoma", "Osteoid Osteoma", "Ewing Sarcoma", "Osteomyelitis"]', 1, 'Osteoid osteoma is a benign, painful tumor. (Nelson Essentials)'),
    (v_topic_id, '318: A child presents with a "painless" limp and limited hip internal rotation. Diagnosis?', '["SCFE", "Legg-Calve-Perthes", "Septic arthritis", "DDH"]', 1, 'LCP is idiopathic avascular necrosis. (Nelson Essentials)'),
    (v_topic_id, '319: A 13-year-old presents with knee pain and a tender tibial tubercle. Diagnosis?', '["Sinding-Larsen", "Osgood-Schlatter", "Patellar tendonitis", "Osteosarcoma"]', 1, 'Osgood-Schlatter is a common adolescent overuse injury. (Nelson Essentials)'),
    (v_topic_id, '320: A child presents with "multiple joint pain" and "fever" for > 6 weeks. Diagnosis?', '["Rheumatic Fever", "Juvenile Idiopathic Arthritis", "Septic arthritis", "SLE"]', 1, 'Systemic JIA includes a characteristic rash and fever. (Nelson Essentials)'),
    (v_topic_id, '321: A girl with oligoarticular JIA needs regular screening for what?', '["Heart failure", "Uveitis", "Renal failure", "Anemia"]', 1, 'Uveitis can be asymptomatic and lead to vision loss. (Nelson Essentials)'),
    (v_topic_id, '322: A child presents with "malar rash," "arthritis," and "hematuria." Diagnosis?', '["HSP", "Systemic Lupus Erythematosus", "JIA", "Kawasaki"]', 1, 'SLE is an autoimmune disease with multi-organ involvement. (Nelson Essentials)'),
    (v_topic_id, '323: A child presents with "heliotrope rash" and "Gottron papules." Diagnosis?', '["SLE", "Juvenile Dermatomyositis", "Scleroderma", "Psoriasis"]', 1, 'JDM involves both skin findings and muscle weakness. (Nelson Essentials)'),
    (v_topic_id, '324: A child presents with "recurrent" fever and "abdominal pain." He is of Sephardic Jewish descent. Diagnosis?', '["Familial Mediterranean Fever", "Still''s", "SLE", "IBD"]', 0, 'FMF is caused by mutations in the MEFV gene. (Nelson Essentials)'),
    (v_topic_id, '325: What is the most common cause of "bacterial meningitis" in a 10-year-old?', '["GBS", "Streptococcus pneumoniae", "E. coli", "Listeria"]', 1, 'S. pneumo is a leading cause in post-neonatal children. (Nelson Essentials)'),
    (v_topic_id, '326: Bacterial meningitis typically has what CSF findings?', '["High glucose", "Low glucose, high protein, high neutrophils", "Normal glucose", "Low protein"]', 1, 'Bacterial consumption of glucose and inflammation drive these changes. (Nelson Essentials)'),
    (v_topic_id, '327: Viral (aseptic) meningitis typically has what CSF findings?', '["Low glucose", "Normal glucose, mildly high protein, lymphocytes", "High glucose", "High neutrophils"]', 1, 'Lymphocytes predominate in viral infections. (Nelson Essentials)'),
    (v_topic_id, '328: A child presents with "fever," "altered mental status," and "focal seizures." Diagnosis?', '["Meningitis", "Encephalitis", "Abscess", "Stroke"]', 1, 'Altered mental status suggests parenchymal involvement. (Nelson Essentials)'),
    (v_topic_id, '329: Which cause of encephalitis is treatable with Acyclovir?', '["Enterovirus", "Herpes Simplex Virus", "West Nile", "Influenza"]', 1, 'HSV-1 or HSV-2 can cause devastating encephalitis. (Nelson Essentials)'),
    (v_topic_id, '330: A child presents with headache, fever, and a "ring-enhancing" lesion on CT. Diagnosis?', '["Tumor", "Brain Abscess", "Stroke", "Meningitis"]', 1, 'Abscesses often arise from contiguous infection like sinusitis. (Nelson Essentials)'),
    (v_topic_id, '331: A child presents with "recurrent" pneumonia and "steatorrhea." Diagnosis?', '["Celiac", "Cystic Fibrosis", "Lactose intolerance", "IBD"]', 1, 'CF is a multi-system disease affecting secretion. (Nelson Essentials)'),
    (v_topic_id, '332: What is the diagnostic test for Cystic Fibrosis?', '["X-ray", "Sweat Chloride Test", "Sputum", "Fecal fat"]', 1, 'Chloride levels are elevated in CF sweat. (Nelson Essentials)'),
    (v_topic_id, '333: A child presents with "diarrhea," "weight loss," and itchy blisters. Diagnosis?', '["IBD", "Celiac Disease", "Food allergy", "Gastroenteritis"]', 1, 'Dermatitis herpetiformis is linked to gluten sensitivity. (Nelson Essentials)'),
    (v_topic_id, '334: What is the screening test for Celiac Disease?', '["Anti-gliadin", "Tissue Transglutaminase (tTG) IgA", "Colonoscopy", "Stool"]', 1, 'tTG IgA is the preferred initial test. (Nelson Essentials)'),
    (v_topic_id, '335: A child presents with bloody diarrhea and continuous colonic inflammation. Diagnosis?', '["Crohn", "Ulcerative Colitis", "Infection", "HSP"]', 1, 'UC is limited to the colon and rectum. (Nelson Essentials)'),
    (v_topic_id, '336: A child presents with skip lesions and perianal tags. Diagnosis?', '["UC", "Crohn Disease", "Celiac", "Amoebiasis"]', 1, 'Crohn''s is a transmural disease. (Nelson Essentials)'),
    (v_topic_id, '337: A child presents with diarrhea after antibiotics. Diagnosis?', '["Salmonella", "Clostridioides difficile", "Rotavirus", "Giardia"]', 1, 'C. diff is an opportunistic overgrowth. (Nelson Essentials)'),
    (v_topic_id, '338: Bloody diarrhea after eating a rare hamburger suggests which organism?', '["Salmonella", "E. coli O157:H7", "Shigella", "Campylobacter"]', 1, 'STEC can cause HUS. (Nelson Essentials)'),
    (v_topic_id, '339: Common cause of winter diarrhea in an unimmunized child?', '["Rotavirus", "Norovirus", "Adenovirus", "E. coli"]', 0, 'Rotavirus is a major cause of dehydration in infants. (Nelson Essentials)'),
    (v_topic_id, '340: Greasy, foul stools after a camping trip suggest what?', '["Giardia lamblia", "Cryptosporidium", "Entamoeba", "Salmonella"]', 0, 'Giardia is a common waterborne parasite. (Nelson Essentials)'),
    (v_topic_id, '341: What is the treatment for Giardia?', '["Amoxicillin", "Metronidazole", "Azithromycin", "Cipro"]', 1, 'Metronidazole is the standard treatment. (Nelson Essentials)'),
    (v_topic_id, '342: Perianal itching at night is classic for what?', '["Pinworms", "Hookworms", "Ascariasis", "Scabies"]', 0, 'Enterobius vermicularis is common in children. (Nelson Essentials)'),
    (v_topic_id, '343: Diagnostic test for pinworms?', '["O\u0026P", "Scotch tape test", "Blood", "X-ray"]', 1, 'The tape test identifies eggs on the skin. (Nelson Essentials)'),
    (v_topic_id, '344: Iron deficiency and ground itch suggest what?', '["Ascaris", "Hookworms", "Pinworms", "Tapeworms"]', 1, 'Hookworm larvae penetrate the skin. (Nelson Essentials)'),
    (v_topic_id, '345: Extreme weight loss and lanugo in a 15-year-old suggests?', '["Bulimia", "Anorexia Nervosa", "Depression", "Hyperthyroid"]', 1, 'Anorexia is a severe eating disorder. (Nelson Essentials)'),
    (v_topic_id, '346: Parotid swelling and dental erosion suggest?', '["Mumps", "Bulimia Nervosa", "Sjogren", "Abscess"]', 1, 'Self-induced vomiting causes these signs. (Nelson Essentials)'),
    (v_topic_id, '347: Refeeding syndrome is characterized by which dangerous electrolyte shift?', '["Hyperkalemia", "Hypophosphatemia", "Hypercalcemia", "Hyponatremia"]', 1, 'Refeeding triggers insulin-mediated phosphate uptake. (Nelson Essentials)'),
    (v_topic_id, '348: Scrotal pain that improves with elevation is more likely to be?', '["Torsion", "Epididymitis", "Hydrocele", "Spermatocele"]', 1, 'A positive Prehn sign suggests epididymitis. (Nelson Essentials)'),
    (v_topic_id, '349: Renal artery bruits and hypertension in a child suggests?', '["Fibromuscular Dysplasia", "Coarctation", "Essential HTN", "Diabetes"]', 0, 'FMD is a major cause of renovascular HTN. (Nelson Essentials)'),
    (v_topic_id, '350: Sudden curtain-like loss of vision suggests?', '["Occlusion", "Optic Neuritis", "Glaucoma", "Retinal Detachment"]', 3, 'Retinal detachment is a surgical emergency. (Nelson Essentials)'),
    (v_topic_id, '351: Can a 15-year-old consent to STI testing in most US states?', '["Yes", "No", "Only if pregnant", "Only if married"]', 0, 'Minors generally have the right to confidential STI care. (Nelson Essentials)'),
    (v_topic_id, '352: Which minor is legally "emancipated"?', '["A 17-year-old student", "A 16-year-old in the military", "A 15-year-old with a job", "A 14-year-old living alone"]', 1, 'Military service usually grants legal emancipation. (Nelson Essentials)'),
    (v_topic_id, '353: Formula for uncuffed ET tube size in a child > 2 years?', '["(Age/4) + 4", "(Age/2) + 12", "Weight / 2", "Age + 10"]', 0, 'The Cole formula is used to estimate size. (PALS Guidelines)'),
    (v_topic_id, '354: Preferred site for pediatric IO access?', '["Femur", "Proximal tibia", "Sternum", "Iliac crest"]', 1, 'The proximal tibia has a wide flat surface for IO. (PALS Guidelines)'),
    (v_topic_id, '355: Leading cause of sudden cardiac death in young athletes?', '["Myocarditis", "Hypertrophic Cardiomyopathy", "Long QT", "Commotio Cordis"]', 1, 'HCM involves asymmetric septal hypertrophy. (Nelson Essentials)'),
    (v_topic_id, '356: What is Commotio Cordis?', '["Viral infection", "VF from blunt chest blow during T-wave", "Congenital defect", "Aortic rupture"]', 1, 'It is an impact-triggered arrhythmia. (Nelson Essentials)'),
    (v_topic_id, '357: Term for reversal of left-to-right shunt due to pulmonary HTN?', '["Eisenmenger", "Fallot", "Ductal dependency", "Cyanotic spell"]', 0, 'Eisenmenger syndrome leads to cyanosis. (Nelson Essentials)'),
    (v_topic_id, '358: Cardinal signs of pediatric CHF include?', '["Sweating, tachycardia, hepatomegaly", "Hypotension", "Anuria", "Rash"]', 0, 'Congestive heart failure presents with poor perfusion and congestion. (Nelson Essentials)'),
    (v_topic_id, '359: Preferred approach for emergency pericardiocentesis?', '["Subxiphoid", "2nd ICS", "5th ICS", "RUQ"]', 0, 'Subxiphoid approach minimizes risk of lung injury. (PALS Guidelines)'),
    (v_topic_id, '360: Most common organism in VP shunt infections?', '["S. pneumo", "Staphylococcus epidermidis", "E. coli", "Neisseria"]', 1, 'Coag-negative staph often colonizes foreign bodies. (Nelson Essentials)'),
    (v_topic_id, '361: APGAR score is used for?', '["Prognosis", "Assessing newborn transition", "Diagnosing brain injury", "Antibiotics"]', 1, 'APGAR evaluates the immediate response to birth. (Nelson Essentials)'),
    (v_topic_id, '362: Most common cause of low APGAR scores?', '["Genetics", "Hypoxia/Respiratory depression", "Heart anomaly", "Infection"]', 1, 'Hypoxia is the primary driver of low scores. (Nelson Essentials)'),
    (v_topic_id, '363: First step in neonatal resuscitation if HR < 100?', '["Compressions", "Positive Pressure Ventilation", "Epinephrine", "Intubate"]', 1, 'Ventilation is the priority in NRP. (NRP Guidelines)'),
    (v_topic_id, '364: When to start chest compressions in NRP?', '["HR < 100", "HR < 60 despite effective PPV", "Always", "If dead"]', 1, 'Compressions start if HR stays below 60 after PPV. (NRP Guidelines)'),
    (v_topic_id, '365: Goal for temperature management after cardiac arrest?', '["Rewarm to 40 C", "Maintain normothermia (36-37.5 C)", "Fever", "Cool to 28 C"]', 1, 'Hyperthermia must be avoided post-arrest. (PALS Guidelines)'),
    (v_topic_id, '366: Primary determinant of outcome in drowning?', '["Hypothermia", "Laryngospasm", "Duration of hypoxia", "Pneumonia"]', 2, 'Hypoxic brain injury is the main cause of death. (Nelson Essentials)'),
    (v_topic_id, '367: Hilar nodes and night sweats in a child suggests?', '["Leukemia", "Tuberculosis", "Lymphoma", "Sarcoid"]', 1, 'Pulmonary TB is a major global concern. (Nelson Essentials)'),
    (v_topic_id, '368: Acute knee swelling and tick bite in CT suggests?', '["Septic", "Lyme Arthritis", "JIA", "Trauma"]', 1, 'Lyme arthritis is a late manifestation. (Nelson Essentials)'),
    (v_topic_id, '369: Sore throat, posterior nodes, and splenomegaly suggest?', '["Strep", "Infectious Mononucleosis", "CMV", "Diphtheria"]', 1, 'EBV is the classic cause of mono. (Nelson Essentials)'),
    (v_topic_id, '370: Treating mono with amoxicillin often causes?', '["Cure", "Diffuse maculopapular rash", "Jaundice", "No reaction"]', 1, 'The rash is an immunologic reaction to the drug. (Nelson Essentials)');
